    function Tout = appendCompatTable(Ta, Tb)
        if ~(istable(Ta) && ~isempty(Ta))
            if istable(Tb)
                Tout = Tb;
            else
                Tout = table();
            end
            return;
        end
        if ~(istable(Tb) && ~isempty(Tb))
            Tout = Ta;
            return;
        end
        vars = union(string(Ta.Properties.VariableNames), string(Tb.Properties.VariableNames), "stable");
        Ta = sixgr.truth.CoupledTruthRuntime.ensureTableVars(Ta, vars, Tb);
        Tb = sixgr.truth.CoupledTruthRuntime.ensureTableVars(Tb, vars, Ta);
        for i = 1:numel(vars)
            v = char(vars(i));
            [Ta.(v), Tb.(v)] = sixgr.truth.CoupledTruthRuntime.harmonizeColumns(Ta.(v), Tb.(v));
        end
        Tout = [Ta(:, cellstr(vars)); Tb(:, cellstr(vars))];
    end

    function T = replaceCompatTableRow(T, rowIndex, sourceRow)
        % Replace one runtime-state row without relying on MATLAB's strict
        % table-to-table storage-class identity.  CSV recovery can load text
        % variables as cells while an in-memory producer naturally emits
        % strings.  Normalize each affected column through the same contract
        % used by appendCompatTable, then update the existing row.  This is
        % a representation repair only; values are neither defaulted nor
        % inferred.
        if ~(istable(T) && istable(sourceRow) && height(sourceRow) == 1)
            error("sixgr:truth:InvalidCompatibleTableRowReplacement", ...
                "Runtime table row replacement requires a table and one source row.");
        end
        rowIndex = double(rowIndex);
        if ~(isscalar(rowIndex) && isfinite(rowIndex) && ...
                rowIndex == round(rowIndex) && rowIndex >= 1 && ...
                rowIndex <= height(T))
            error("sixgr:truth:InvalidCompatibleTableRowIndex", ...
                "Runtime table row replacement index is outside the destination table.");
        end
        destinationVars = string(T.Properties.VariableNames);
        sourceVars = string(sourceRow.Properties.VariableNames);
        missingVars = setdiff(destinationVars, sourceVars, "stable");
        if ~isempty(missingVars)
            error("sixgr:truth:IncompleteCompatibleTableRow", ...
                "Runtime replacement row is missing destination variables: %s.", ...
                strjoin(missingVars, ", "));
        end
        for variableIndex = 1:numel(destinationVars)
            variableName = char(destinationVars(variableIndex));
            [destinationColumn, sourceColumn] = ...
                sixgr.truth.CoupledTruthRuntime.harmonizeColumns( ...
                T.(variableName), sourceRow.(variableName));
            if size(sourceColumn, 1) ~= 1 || ...
                    size(sourceColumn, 2) ~= size(destinationColumn, 2)
                error("sixgr:truth:IncompatibleRuntimeTableColumnShape", ...
                    "Runtime replacement column %s has incompatible shape.", ...
                    variableName);
            end
            destinationColumn(rowIndex, :) = sourceColumn(1, :);
            T.(variableName) = destinationColumn;
        end
    end

    function tf = isCSIReportOccasion(cfg, sourceSlot, direction)
        direction = upper(strtrim(string(direction)));
        if direction == "UL"
            % UL receiver CSI is internal gNB measurement rather than a UE
            % PUCCH report. Preserve every decoded PUSCH measurement for
            % causal UL link adaptation.
            tf = true;
            return;
        end
        reportEnabled = logical(sixgr.util.structGet(cfg, ...
            "phy.csi.reportCSI", false));
        if ~reportEnabled
            tf = false;
            return;
        end
        trigger = lower(strtrim(string(sixgr.util.structGet(cfg, ...
            "phy.csi.reportTrigger", ""))));
        if strlength(trigger) == 0
            error("sixgr:truth:MissingCSIReportTrigger", ...
                "Enabled DL CSI reporting requires YAML-resolved report-trigger authority.");
        end
        sourceSlot = round(double(sourceSlot));
        if ~(isscalar(sourceSlot) && isfinite(sourceSlot) && sourceSlot >= 1)
            error("sixgr:truth:InvalidCSIReportSourceSlot", ...
                "CSI report timing requires a finite one-based runtime source slot.");
        end
        switch trigger
            case "periodic"
                period = double(sixgr.util.structGet(cfg, ...
                    "phy.csi.reportPeriodicitySlots", NaN));
                offset = double(sixgr.util.structGet(cfg, ...
                    "phy.csi.reportOffsetSlots", NaN));
                if ~(isscalar(period) && isfinite(period) && period >= 1 && ...
                        period == round(period) && isscalar(offset) && ...
                        isfinite(offset) && offset >= 0 && ...
                        offset == round(offset) && offset < period)
                    error("sixgr:truth:InvalidCSIReportTiming", ...
                        "Periodic CSI reporting requires exact integer period/offset authority.");
                end
                % Runtime slots are persisted one-based; configured NR slot
                % offsets are zero-based within the reporting period.
                tf = mod((sourceSlot - 1) - offset, period) == 0;
            case {"semi_persistent","aperiodic"}
                % Trigger-state installation is not inferred from a data
                % grant. Until the explicit MAC/RRC trigger is present,
                % fail closed instead of fabricating a report occasion.
                tf = false;
            otherwise
                error("sixgr:truth:InvalidCSIReportTrigger", ...
                    "Unsupported CSI report trigger %s.", char(trigger));
        end
    end

    function Tout = appendObservedREAllocation(Ta, Tb)
        % Exact duplicate rows can be replayed when a completed PHY result
        % is merged back into the coupled runtime.  They describe the same
        % physical RE observation and are retained exactly once.  Distinct
        % allocation rows, including genuine overlaps, are not collapsed.
        Tout = sixgr.truth.CoupledTruthRuntime.appendCompatTable(Ta, Tb);
        Tout = sixgr.truth.deduplicateObservedREAllocation(Tout);
    end

    function T = ensureTableVars(T, vars, refT)
        for i = 1:numel(vars)
            v = char(vars(i));
            if ~ismember(v, T.Properties.VariableNames)
                T.(v) = sixgr.truth.CoupledTruthRuntime.defaultColumnLike(refT, v, height(T));
            end
        end
    end

    function [lhs, rhs] = harmonizeStructArray(lhs, rhs)
        if ~isstruct(lhs)
            lhs = struct();
        end
        if ~isstruct(rhs)
            rhs = struct();
        end
        lhsFields = string(fieldnames(lhs));
        rhsFields = string(fieldnames(rhs));
        allFields = union(lhsFields, rhsFields, "stable");
        for i = 1:numel(allFields)
            fieldName = char(allFields(i));
            if ~isfield(lhs, fieldName)
                [lhs(1:numel(lhs)).(fieldName)] = deal([]);
            end
            if ~isfield(rhs, fieldName)
                [rhs(1:numel(rhs)).(fieldName)] = deal([]);
            end
        end
    end

    function col = defaultColumnLike(refT, varName, nRows)
        if istable(refT) && ismember(varName, refT.Properties.VariableNames)
            refVal = refT.(varName);
            if isstring(refVal)
                col = strings(nRows, 1);
                return;
            end
            if iscellstr(refVal) || iscell(refVal) || ischar(refVal)
                col = strings(nRows, 1);
                return;
            end
            if islogical(refVal)
                col = false(nRows, 1);
                return;
            end
            if isnumeric(refVal)
                col = nan(nRows, 1);
                return;
            end
        end
        col = strings(nRows, 1);
    end

    function [a, b] = harmonizeColumns(a, b)
        if isstring(a) || isstring(b) || iscellstr(a) || iscellstr(b) || iscell(a) || iscell(b) || ischar(a) || ischar(b)
            a = sixgr.truth.CoupledTruthRuntime.normalizeStringColumn(a);
            b = sixgr.truth.CoupledTruthRuntime.normalizeStringColumn(b);
            a = a(:);
            b = b(:);
            return;
        end
        if islogical(a) && isnumeric(b)
            b = logical(b);
            return;
        end
        if isnumeric(a) && islogical(b)
            a = logical(a);
            return;
        end
    end

    function out = normalizeStringColumn(value)
        if isstring(value)
            out = value;
            return;
        end
        if ischar(value)
            out = string(value);
            return;
        end
        if iscell(value)
            out = strings(numel(value), 1);
            for ii = 1:numel(value)
                item = value{ii};
                if isempty(item)
                    out(ii) = "";
                elseif isstring(item)
                    out(ii) = item(1);
                elseif ischar(item)
                    out(ii) = string(item);
                elseif isnumeric(item) || islogical(item)
                    out(ii) = string(item(1));
                else
                    out(ii) = string(class(item));
                end
            end
            return;
        end
        out = string(value);
    end

