    function T = annotateControlReferenceTrialTableImpl(state, signalName, T)
        if nargin < 3 || ~istable(T)
            T = table();
        end
        if isempty(T)
            return;
        end
        signalName = upper(strtrim(string(signalName)));
        n = height(T);
        meta = sixgr.truth.CoupledTruthRuntime.runtimeExportMetadata(state);
        [classification, materialization, gatingEffect, consumer] = ...
            sixgr.truth.CoupledTruthRuntime.controlReferenceTruthTokens(signalName);

        status = upper(strtrim(string(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "Status", repmat("", n, 1)))));
        crcPass = double(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "CRCPass", nan(n, 1)));
        decodeSuccess = isfinite(crcPass) & crcPass ~= 0;
        decodeSuccess(~isfinite(crcPass) & status == "PASS") = true;
        pendingMask = status == "PENDING" | contains(status, "PENDING");
        failureFlag = (status == "FAIL" | status == "CRASH") | (~decodeSuccess & ~pendingMask & status ~= "" & status ~= "NA");
        observationAvailable = ~pendingMask & status ~= "CRASH";
        if signalName == "CSI-RS"
            scheduled = logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                T, "Scheduled", false(n, 1)));
            transmitted = logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                T, "Transmitted", false(n, 1)));
            observed = logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                T, "Observed", false(n, 1)));
            consumed = logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                T, "Consumed", false(n, 1)));
            measuredCSI = logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                T, "CSIMeasurementAvailable", false(n, 1)));
            channelEstimate = logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                T, "ChannelEstimateAvailable", false(n, 1)));
            observationAvailable = transmitted & observed;
            decodeSuccess = observationAvailable & channelEstimate & ...
                (consumed | measuredCSI);
            pendingMask = scheduled & ~transmitted;
            failureFlag = scheduled & transmitted & ~decodeSuccess;
        end

        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "SignalFamily", signalName, true);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "SourceClassification", classification, true);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "RuntimeMaterializationStatus", materialization, true);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "ControlGatingEffect", gatingEffect, true);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "RuntimeStateConsumer", consumer, false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "RuntimeConsumer", consumer, false);
        T = sixgr.truth.CoupledTruthRuntime.applyPRACHFullRARuntimeTokens(signalName, T);
        T = sixgr.truth.CoupledTruthRuntime.setLogicalColumn(T, "DecodeSuccess", decodeSuccess);
        T = sixgr.truth.CoupledTruthRuntime.setLogicalColumn(T, "SuccessFlag", decodeSuccess);
        T = sixgr.truth.CoupledTruthRuntime.setLogicalColumn(T, "FailureFlag", failureFlag);
        T = sixgr.truth.CoupledTruthRuntime.setLogicalColumn(T, "ControlObservationAvailable", observationAvailable);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "ValueSource", "runtime_control_reference_signal_observation", false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "ValueRole", "control_reference_signal_runtime_evidence", false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "ValueStatus", "available_runtime_observation", false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "ValueDefinition", "canonical control/reference-signal row emitted by the active LLS coupled runtime", false);
        T = sixgr.truth.CoupledTruthRuntime.setLogicalColumn(T, "FinalizedFlag", ~pendingMask);
        T = sixgr.truth.CoupledTruthRuntime.setLogicalColumn(T, "PlaceholderFlag", false(n, 1));
        T = sixgr.truth.CoupledTruthRuntime.setLogicalColumn(T, "FallbackFlag", false(n, 1));
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "NAReason", "", false);
        T = sixgr.truth.CoupledTruthRuntime.applyRuntimeMetadataColumns(T, meta, signalName);
        directionValues = string(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "Direction", repmat("", n, 1)));
        if ~ismember("Direction", string(T.Properties.VariableNames))
            directionValues = string(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "LinkDirection", repmat("", n, 1)));
            if all(strlength(strtrim(directionValues)) == 0)
                directionValues = string(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "TrialDirection", repmat("", n, 1)));
            end
            if all(strlength(strtrim(directionValues)) == 0)
                directionValues = string(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "GrantDirection", repmat("", n, 1)));
            end
            if any(strlength(strtrim(directionValues)) > 0)
                T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "Direction", directionValues, false);
            end
        end
        directionValues = string(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "Direction", repmat("", n, 1)));
        if any(strlength(strtrim(directionValues)) > 0)
            T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "TrialDirection", directionValues, false);
            T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "LinkDirection", directionValues, false);
            T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "GrantDirection", directionValues, false);
        end
        T = sixgr.truth.CoupledTruthRuntime.annotateControlReferenceSINRColumnsImpl(signalName, T);

        if signalName == "TRS"
            trsCtx = sixgr.truth.CoupledTruthRuntime.resolveTRSControlAnnotationContext(state, T);
            T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "TRSStateSource", string(trsCtx.TRSStateSource), false);
            T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "TRSRuntimeConsumer", string(trsCtx.TRSRuntimeConsumer), false);
            T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "TRSReceiverIntegrationStatus", string(trsCtx.TRSReceiverIntegrationStatus), false);
            T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "TRSReceiverIntegrationBlocker", string(trsCtx.TRSReceiverIntegrationBlocker), false);
            T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "TRSReceiverConsumerType", string(trsCtx.TRSReceiverConsumerType), false);
            T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "TRSTrackingStateBefore", string(trsCtx.TRSTrackingStateBefore), false);
            T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "TRSTrackingStateAfter", string(trsCtx.TRSTrackingStateAfter), false);
            T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "TRSUpdateOutcome", string(trsCtx.TRSUpdateOutcome), false);
            T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "TRSChannelTrackingFreshnessState", string(trsCtx.TRSChannelTrackingFreshnessState), false);
            T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "TRSFrequencyTrackingState", string(trsCtx.TRSFrequencyTrackingState), false);
            T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "TRSTimingTrackingState", string(trsCtx.TRSTimingTrackingState), false);
            T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "TRSRuntimeEvidenceSource", string(trsCtx.TRSRuntimeEvidenceSource), false);
            if ~ismember("TRSProcessed", string(T.Properties.VariableNames))
                T.TRSProcessed = repmat(logical(trsCtx.TRSProcessed), n, 1);
            end
            T = sixgr.truth.CoupledTruthRuntime.setNumericColumn(T, "TRSTrackingUpdateTime_s", repmat(double(trsCtx.TRSTrackingUpdateTime_s), n, 1), false);
            T = sixgr.truth.CoupledTruthRuntime.setNumericColumn(T, "TRSAssociatedCell", repmat(double(trsCtx.TRSAssociatedCell), n, 1), false);
            if ~ismember("TRSTimingEstimateAvailable", string(T.Properties.VariableNames))
                T.TRSTimingEstimateAvailable = repmat(logical(trsCtx.TRSTimingEstimateAvailable), n, 1);
            end
            T = sixgr.truth.CoupledTruthRuntime.setNumericColumn(T, "TRSTimingEstimate_samples", repmat(double(trsCtx.TRSTimingEstimate_samples), n, 1), false);
            if ~ismember("TRSCFOEstimateAvailable", string(T.Properties.VariableNames))
                T.TRSCFOEstimateAvailable = repmat(logical(trsCtx.TRSCFOEstimateAvailable), n, 1);
            end
            T = sixgr.truth.CoupledTruthRuntime.setNumericColumn(T, "TRSEstimatedCFO_Hz", repmat(double(trsCtx.TRSEstimatedCFO_Hz), n, 1), false);
        end
        T = sixgr.truth.CoupledTruthRuntime.fillBlankCategoricalColumns(T, lower(strrep(char(signalName), "-", "_")));
    end

    function T = annotatePUCCHGrantTraceTableImpl(state, T)
        if nargin < 2 || ~istable(T)
            T = table();
        end
        if isempty(T)
            return;
        end
        n = height(T);
        meta = sixgr.truth.CoupledTruthRuntime.runtimeExportMetadata(state);
        executed = logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "GrantExecutedFlag", false(n, 1)));
        canceled = logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "CanceledAtSweepBoundary", false(n, 1)));
        rightCensored = logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "RightCensored", false(n, 1)));
        standaloneDecodeOk = logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "PUCCHDecodeOk", false(n, 1)));
        multiplexed = logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "MultiplexedOnPUSCH", false(n, 1)));
        runtimeStateUpdated = logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "RuntimeStateUpdated", false(n, 1)));
        puschUCIDecodeOk = logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "PUSCHUCIDecodeOk", false(n, 1)));
        transferred = multiplexed & runtimeStateUpdated;
        observed = executed | transferred;
        decodeOk = (executed & standaloneDecodeOk) | (transferred & puschUCIDecodeOk);
        crashed = logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "Crash", false(n, 1)));
        status = strtrim(string(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "Status", repmat("", n, 1))));
        blank = strlength(status) == 0;
        status(blank & ~observed) = "PENDING";
        status(transferred & decodeOk) = "PASS";
        status(transferred & ~decodeOk & ~crashed) = "FAIL";
        status(blank & executed & decodeOk) = "PASS";
        status(blank & executed & ~decodeOk & ~crashed) = "FAIL";
        status(blank & crashed) = "CRASH";
        status(canceled) = "CANCELED";
        status(rightCensored) = "RIGHT_CENSORED";
        T.Status = status;

        classification = repmat("active_integrated", n, 1);
        classification(~observed & ~canceled & ~rightCensored) = "active_but_simplified";
        materialization = repmat("active_integrated_waveform_feedback_runtime", n, 1);
        materialization(transferred) = "active_integrated_pusch_uci_feedback_runtime";
        materialization(~observed & ~canceled & ~rightCensored) = "active_scheduled_pending_feedback_due_not_reached";
        materialization(canceled) = "active_scheduled_feedback_canceled_at_independent_snr_boundary";
        materialization(rightCensored) = "active_scheduled_feedback_right_censored_at_finite_horizon";
        materialization(executed & crashed) = "active_waveform_feedback_execution_crashed";

        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "SignalFamily", "PUCCH", true);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "SourceClassification", classification, true);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "RuntimeMaterializationStatus", materialization, true);
        uciType = lower(strtrim(string(sixgr.truth.CoupledTruthRuntime. ...
            tableColumnOrDefault(T, "UCIType", repmat("harq_ack", n, 1)))));
        isCSI = contains(uciType, "csi");
        gatingEffect = repmat("harq_feedback_resource_grant_and_state_update_when_due", n, 1);
        gatingEffect(isCSI) = "csi_report_decode_and_link_adaptation_update_when_due";
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "ControlGatingEffect", gatingEffect, true);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "RuntimeStateConsumer", "pending_feedback_due_slot", false);
        if any(observed)
            consumer = string(T.RuntimeStateConsumer);
            consumer(executed & ~isCSI) = "HARQEntity.onFeedback";
            consumer(executed & isCSI) = "CoupledTruthRuntime.processDueFeedback.CSI";
            consumer(transferred & ~isCSI) = "HARQEntity.onFeedback_via_PUSCH_UCI";
            consumer(transferred & isCSI) = "CoupledTruthRuntime.applyDecodedPUSCHUCI.CSI";
            T.RuntimeStateConsumer = consumer;
        end
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "RuntimeConsumer", string(T.RuntimeStateConsumer), true);
        T = sixgr.truth.CoupledTruthRuntime.setLogicalColumn(T, "DecodeSuccess", decodeOk);
        T = sixgr.truth.CoupledTruthRuntime.setLogicalColumn(T, "SuccessFlag", observed & decodeOk);
        T = sixgr.truth.CoupledTruthRuntime.setLogicalColumn(T, "FailureFlag", observed & ~decodeOk);
        T = sixgr.truth.CoupledTruthRuntime.setLogicalColumn(T, "ControlObservationAvailable", observed);
        valueSource = repmat("runtime_pucch_grant_trace", n, 1);
        valueSource(transferred) = "runtime_pusch_uci_feedback_trace";
        valueRole = repmat("explicit_pucch_grant_and_feedback_runtime_state", n, 1);
        valueRole(isCSI) = "explicit_pucch_csi_report_grant_and_decoded_runtime_state";
        valueRole(transferred) = "explicit_pucch_grant_transferred_to_same_waveform_pusch_uci";
        valueRole(transferred & isCSI) = "explicit_csi_report_transferred_to_same_waveform_pusch_uci";
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "ValueSource", valueSource, true);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "ValueRole", valueRole, true);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "ValueStatus", "available_runtime_grant_state", false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "ValueDefinition", "canonical PUCCH grant/resource row; waveform decode fields become available only after the feedback due slot is processed", false);
        T = sixgr.truth.CoupledTruthRuntime.setLogicalColumn(T, "FinalizedFlag", observed | canceled | rightCensored);
        T = sixgr.truth.CoupledTruthRuntime.setLogicalColumn(T, "PlaceholderFlag", false(n, 1));
        T = sixgr.truth.CoupledTruthRuntime.setLogicalColumn(T, "FallbackFlag", false(n, 1));
        naReason = repmat("", n, 1);
        naReason(observed) = "not_applicable_feedback_observed_and_finalized";
        naReason(~observed & ~canceled & ~rightCensored) = "feedback_due_slot_not_reached_in_this_bounded_run";
        naReason(canceled) = "independent_snr_point_boundary_harq_state_reset";
        naReason(rightCensored) = "finite_horizon_right_censor_no_waveform_claim";
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "NAReason", naReason, true);
        T = sixgr.truth.CoupledTruthRuntime.applyRuntimeMetadataColumns(T, meta, "PUCCH");
        T = sixgr.truth.CoupledTruthRuntime.fillBlankCategoricalColumns(T, "pucch_grant_trace");
    end

    function meta = runtimeExportMetadata(state)
        meta = struct("RunID", NaN, "RunUUID", "", "RunTag", "", "ScenarioID", "", "ConfigHash", "");
        storeState = struct();
        try
            storeState = sixgr.db.artifactStore("get_state");
        catch
            storeState = struct();
        end
        cfg = sixgr.util.structGet(state, "CfgMobility", struct());
        meta.RunID = double(sixgr.util.structGet(storeState, "RunID", sixgr.util.structGet(storeState, "run_id", NaN)));
        meta.RunUUID = char(string(sixgr.util.structGet(storeState, "RunUUID", "")));
        meta.RunTag = char(string(sixgr.util.structGet(cfg, "run.runTag", "")));
        meta.ScenarioID = char(string(sixgr.util.structGet(cfg, "run.scenarioID", ...
            sixgr.util.structGet(cfg, "meta.lls6gScenarioID", sixgr.util.structGet(cfg, "meta.loadedFrom", "")))));
        meta.ConfigHash = char(string(sixgr.util.structGet(cfg, "meta.configHash", "")));
    end

    function T = applyRuntimeMetadataColumns(T, meta, signalName)
        n = height(T);
        T = sixgr.truth.CoupledTruthRuntime.setNumericColumn(T, "RunID", repmat(double(meta.RunID), n, 1), false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "RunUUID", string(meta.RunUUID), false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "RunTag", string(meta.RunTag), false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "ScenarioID", string(meta.ScenarioID), false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "ConfigHash", string(meta.ConfigHash), false);
        artifact = "air_interface/csv/" + lower(string(signalName)) + "_trials.csv";
        if upper(string(signalName)) == "CSI-RS"
            artifact = "air_interface/csv/csi_rs_trials.csv";
        end
        if upper(string(signalName)) == "PUCCH" && ismember("PUCCHGrantState", string(T.Properties.VariableNames))
            artifact = "packet_flow/csv/live_pucch_grants.csv";
        end
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "SourceArtifact", artifact, false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "SourceTable", artifact, false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "ArtifactClass", "canonical_control_reference_signal_runtime_evidence", false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "SemanticState", "runtime_populated", false);
    end

    function [classification, materialization, gatingEffect, consumer] = controlReferenceTruthTokens(signalName)
        signalName = upper(string(signalName));
        switch signalName
            case "PBCH"
                classification = "active_integrated";
                materialization = "active_integrated_waveform_cell_search_gate";
                gatingEffect = "cell_acquisition_gate";
                consumer = "CoupledTruthRuntime.applyPBCHTrial";
            case "PRACH"
                classification = "active_but_simplified";
                materialization = "active_but_simplified_waveform_prach_detection_gate_no_full_ra_procedure";
                gatingEffect = "random_access_gate_simplified_ra";
                consumer = "CoupledTruthRuntime.applyPRACHTrial";
            case "PDCCH"
                classification = "active_integrated";
                materialization = "active_integrated_pdcch_blind_dci_crc_cce_reg_evidence";
                gatingEffect = "grant_execution_gate";
                consumer = "CoupledTruthRuntime.applyPDCCHGrantTrial";
            case "PUCCH"
                classification = "active_integrated";
                materialization = "active_integrated_waveform_feedback_runtime";
                gatingEffect = "harq_feedback_state_update";
                consumer = "HARQEntity.onFeedback";
            case "SRS"
                classification = "active_integrated";
                materialization = "active_integrated_waveform_srs_channel_estimation_gate";
                gatingEffect = "srs_freshness_csi_gate";
                consumer = "CoupledTruthRuntime.applySRSTrial";
            case "CSI-RS"
                classification = "active_integrated";
                materialization = "active_integrated_waveform_csirs_channel_estimation_feedback";
                gatingEffect = "dl_csi_feedback_and_link_adaptation_update";
                consumer = "CoupledTruthRuntime.enqueueCSIReport";
            case "TRS"
                classification = "active_integrated";
                materialization = "active_integrated_waveform_trs_shared_receiver_tracking_state";
                gatingEffect = "shared_receiver_tracking_state_feeds_scheduler_eligibility_when_configured";
                consumer = "shared_receiver_tracking_state";
            otherwise
                classification = "missing";
                materialization = "missing_runtime_control_reference_signal";
                gatingEffect = "none";
                consumer = "none";
        end
    end

    function T = applyPRACHFullRARuntimeTokens(signalName, T)
        if upper(string(signalName)) ~= "PRACH" || ~(istable(T) && ~isempty(T))
            return;
        end
        n = height(T);
        raProcedure = lower(strtrim(string(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
            T, "RAProcedureType", repmat("", n, 1)))));
        fullSource = strtrim(string(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
            T, "FullRAEvidenceSource", repmat("", n, 1))));
        raCompleted = sixgr.truth.CoupledTruthRuntime.logicalVectorOrDefault( ...
            sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "RACompleted", false(n, 1)), n, false);
        preambleDetected = sixgr.truth.CoupledTruthRuntime.logicalVectorOrDefault( ...
            sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "PreambleDetected", false(n, 1)), n, false);
        msg2Ok = sixgr.truth.CoupledTruthRuntime.logicalVectorOrDefault( ...
            sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "Msg2RARNTIDetected", false(n, 1)), n, false);
        msg3Ok = sixgr.truth.CoupledTruthRuntime.logicalVectorOrDefault( ...
            sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "Msg3PUSCHCrcPass", false(n, 1)), n, false);
        msg4Ok = sixgr.truth.CoupledTruthRuntime.logicalVectorOrDefault( ...
            sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "Msg4PDSCHCrcPass", false(n, 1)), n, false);
        preambleTx = double(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "PreambleIndexTx", nan(n, 1)));
        rarnti = double(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "RARNTI", nan(n, 1)));
        timingAdvance = double(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, "TimingAdvanceCommand", nan(n, 1)));
        hasMsgEvidence = isfinite(preambleTx) | isfinite(rarnti) | isfinite(timingAdvance) | ...
            preambleDetected | msg2Ok | msg3Ok | msg4Ok;
        hasExplicitFullRA = raProcedure == "contention_based_four_step" | strlength(fullSource) > 0;
        fullAttemptMask = hasExplicitFullRA & hasMsgEvidence;
        failedBeforeEvidence = ...
            upper(strtrim(string(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                T, "Status", repmat("", n, 1))))) == "CRASH" & ...
            string(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                T, "RuntimeEvidenceSource", repmat("", n, 1))) == ...
                "sixgr.phy.ra.runFourStepRA" & ~hasMsgEvidence;
        if any(failedBeforeEvidence)
            % An exception from the strict four-step producer is not an
            % executed simplified PRACH model, nor a receiver measurement.
            T.SourceClassification(failedBeforeEvidence) = "execution_failed";
            T.RuntimeMaterializationStatus(failedBeforeEvidence) = "four_step_ra_runtime_failed";
            T.ControlGatingEffect(failedBeforeEvidence) = "random_access_gate_runtime_execution_failed";
            T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "ValueStatus", "", false);
            T.ValueStatus(failedBeforeEvidence) = "unavailable_runtime_execution_failed";
        end
        rrcRequired = sixgr.truth.CoupledTruthRuntime.logicalVectorOrDefault( ...
            sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, ...
            "RequireRRCSetupComplete", false(n, 1)), n, false);
        rrcOk = sixgr.truth.CoupledTruthRuntime.logicalVectorOrDefault( ...
            sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, ...
            "RRCSetupCompleteDecoded", false(n, 1)), n, false) & ...
            sixgr.truth.CoupledTruthRuntime.logicalVectorOrDefault( ...
            sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault(T, ...
            "RRCConnected", false(n, 1)), n, false);
        completedMask = fullAttemptMask & raCompleted & (~rrcRequired | rrcOk);
        if ~any(fullAttemptMask)
            return;
        end
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "SourceClassification", "", false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "RuntimeMaterializationStatus", "", false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "ControlGatingEffect", "", false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "RuntimeStateConsumer", "", false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "RuntimeConsumer", "", false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "RuntimeEvidenceSource", "", false);
        T = sixgr.truth.CoupledTruthRuntime.setStringColumn(T, "ValueDefinition", "", false);
        % Classification describes execution provenance, not decoder
        % outcome. A waveform-backed attempt that terminates after a missed
        % Msg1 detection is still integrated truth; its status records the
        % causal termination without claiming completion.
        T.SourceClassification(fullAttemptMask) = "active_integrated";
        T.RuntimeMaterializationStatus(fullAttemptMask) = ...
            "active_integrated_four_step_ra_waveform_attempt";
        T.RuntimeMaterializationStatus(fullAttemptMask & ~preambleDetected) = ...
            "active_integrated_four_step_ra_waveform_terminated_at_msg1_detection";
        T.RuntimeMaterializationStatus(fullAttemptMask & preambleDetected & ~raCompleted) = ...
            "active_integrated_four_step_ra_waveform_terminated_before_msg4_completion";
        T.RuntimeMaterializationStatus(fullAttemptMask & raCompleted & rrcRequired & ~rrcOk) = ...
            "active_integrated_initial_access_waveform_terminated_before_rrc_setup_complete";
        T.RuntimeMaterializationStatus(completedMask) = "active_integrated_four_step_ra_waveform_msg1_msg2_msg3_msg4";
        T.RuntimeMaterializationStatus(completedMask & rrcRequired) = ...
            "active_integrated_initial_access_waveform_msg1_msg2_msg3_msg4_rrc_setup_complete";
        T.ControlGatingEffect(fullAttemptMask) = "random_access_gate_full_four_step_ra_attempt";
        T.ControlGatingEffect(completedMask) = "random_access_gate_full_four_step_ra";
        T.RuntimeStateConsumer(fullAttemptMask) = "CoupledTruthRuntime.applyPRACHTrial";
        T.RuntimeConsumer(fullAttemptMask) = "CoupledTruthRuntime.applyPRACHTrial";
        T.RuntimeEvidenceSource(fullAttemptMask) = "sixgr.phy.ra.runFourStepRA";
        T.ValueDefinition(fullAttemptMask) = ...
            "canonical four-step random-access waveform attempt; receiver outcomes and causal termination stage are preserved";
        T.ValueDefinition(completedMask) = "canonical PRACH row backed by Msg1 PRACH, Msg2 RAR, Msg3 PUSCH, and Msg4 contention-resolution waveform evidence";
        T.ValueDefinition(completedMask & rrcRequired) = ...
            "canonical initial-access row backed by Msg1 through Msg4 plus decoded SRB1 RRCSetupComplete PUSCH/UL-SCH waveform evidence";
    end

    function writeRAEvidenceTables(layout, tables)
        if ~isstruct(tables)
            return;
        end
        names = ["ra_attempts","ra_state_transitions","msg1_prach_detection", ...
            "msg2_rar_trials","msg2_pdcch_candidates","msg3_pusch_trials", ...
            "msg4_contention_resolution","rrc_connection_events","rrc_setup_complete", ...
            "ra_timer_events","ra_negative_trials", ...
            "ra_collision_trials","ra_oracle_guard","ra_runtime_stage_waveforms"];
        for i = 1:numel(names)
            f = char(names(i));
            if isfield(tables, f) && istable(tables.(f)) && ...
                    (~isempty(tables.(f)) || width(tables.(f)) > 0)
                artifactPath = fullfile(layout.ControlCSVDir, string(f) + ".csv");
                % A typed zero-row table is the truthful representation of
                % an evaluated-but-disabled campaign.  Never overwrite
                % populated runtime rows with that schema-only artifact.
                if ~isempty(tables.(f)) || exist(artifactPath, "file") ~= 2
                    sixgr.util.csvWriteTable(artifactPath, tables.(f), ...
                        "PreserveSchema", true);
                end
            end
        end
    end

    function values = logicalVectorOrDefault(raw, n, defaultValue)
        n = max(0, round(double(n)));
        if nargin < 3
            defaultValue = false;
        end
        values = repmat(logical(defaultValue), n, 1);
        if isempty(raw)
            return;
        end
        if islogical(raw)
            rawValues = reshape(raw, [], 1);
        elseif isnumeric(raw)
            rawValues = reshape(isfinite(double(raw)) & double(raw) ~= 0, [], 1);
        else
            tokens = lower(strtrim(string(raw)));
            rawValues = reshape(tokens == "true" | tokens == "1" | tokens == "yes" | ...
                tokens == "pass" | tokens == "passed", [], 1);
        end
        if isempty(rawValues)
            return;
        end
        if numel(rawValues) == 1 && n ~= 1
            rawValues = repmat(rawValues(1), n, 1);
        elseif numel(rawValues) ~= n
            rawValues = rawValues(1:min(numel(rawValues), n));
            if numel(rawValues) < n
                rawValues(end+1:n, 1) = logical(defaultValue);
            end
        end
        values = logical(rawValues);
    end

    function value = tableColumnOrDefault(T, name, defaultValue)
        if istable(T) && ismember(string(name), string(T.Properties.VariableNames))
            value = T.(char(name));
        else
            value = defaultValue;
        end
    end

    function T = fillBlankCategoricalColumns(T, scopeToken)
        T = sixgr.truth.fillBlankCategoricalColumns(T, scopeToken);
    end

    function tf = isImmutableIdentityField(fieldName)
        tf = sixgr.truth.isImmutableIdentityField(fieldName);
    end

    function token = blankCategoricalToken(fieldName, scopeToken)
        scope = string(scopeToken);
        fieldName = lower(char(string(fieldName)));
        if strcmp(fieldName, "usedoraclefields")
            token = "";
        elseif endsWith(fieldName, "source")
            token = "not_emitted_by_active_" + scope + "_runtime";
        elseif endsWith(fieldName, "valuerole")
            token = "not_available";
        elseif endsWith(fieldName, "valuestatus")
            token = "not_emitted_by_active_" + scope + "_runtime";
        elseif endsWith(fieldName, "nareason") || strcmp(fieldName, "nareason") || strcmp(fieldName, "unavailablereason")
            token = "field_not_emitted_by_active_" + scope + "_runtime";
        elseif contains(fieldName, "blocker")
            token = "not_blocked_in_active_" + scope + "_runtime";
        elseif contains(fieldName, "definition")
            token = "not_emitted_by_active_" + scope + "_runtime";
        elseif contains(fieldName, "authority")
            token = "not_recorded_by_active_" + scope + "_runtime";
        else
            token = "not_applicable_for_active_" + scope + "_runtime";
        end
    end

    function tf = isSemanticCategoricalField(fieldName, rawCol)
        name = lower(char(string(fieldName)));
        if isstring(rawCol) || ischar(rawCol) || iscell(rawCol) || iscategorical(rawCol)
            tf = true;
            return;
        end
        if ~(isnumeric(rawCol) || islogical(rawCol))
            tf = false;
            return;
        end
        numericNameHints = ["_db","db","_hz","hz","_deg","deg","_ms","ms","_s","_bits","bits","_bytes","bytes","count","index","slot","frame","time","cellid","ueid","ueindex","rnti","rank","layers","ports","prb","rb","resourceid","setid","iterations","power","gain","ratio","correlation","probability","rate","latency","throughput","error"];
        if any(contains(name, numericNameHints))
            tf = false;
            return;
        end
        semanticHints = ["source","valuerole","valuestatus","nareason","unavailablereason","definition","availability","modulation","mode","policy","strategy","table","type","hex","consumer","classification","materialization","gating","blocker","authority","beam","precoder","interferer","tracking","outcome"];
        semanticExact = ["cqitable","mcstable","pmitype","pmicodebookmode","csireportmode","csipayloadhex","iqimbalancemodel","iqimbalancemeasurementsource","iqimbalancemeasurementstatus","measuredtrialsinrsource","largescalesinrsource","servingrsrpsource","csi_rsrpsource","appliedlargescalegainsource","interferencemode","requestedvsappliedprecoderpmimatchstatus"];
        tf = any(strcmp(name, semanticExact)) || any(contains(name, semanticHints));
    end

    function T = setStringColumn(T, name, value, overwrite)
        n = height(T);
        if isscalar(value)
            value = repmat(string(value), n, 1);
        else
            value = reshape(string(value), [], 1);
            if numel(value) ~= n
                value = repmat(value(1), n, 1);
            end
        end
        if ~ismember(string(name), string(T.Properties.VariableNames)) || logical(overwrite)
            T.(char(name)) = value;
            return;
        end
        current = string(T.(char(name)));
        if numel(current) ~= n
            current = reshape(current, [], 1);
        end
        normalized = lower(strtrim(current));
        blank = strlength(strtrim(current)) == 0 | normalized == "missing" | normalized == "<missing>" | normalized == "nan";
        current(blank) = value(blank);
        T.(char(name)) = current;
    end

    function T = setStringValueAt(T, name, idx, value)
        n = height(T);
        idx = unique(round(double(idx(:))), "stable");
        idx = idx(isfinite(idx) & idx >= 1 & idx <= n);
        if isempty(idx)
            return;
        end
        field = char(name);
        if ismember(string(name), string(T.Properties.VariableNames))
            current = reshape(string(T.(field)), [], 1);
            if numel(current) ~= n
                current = repmat("", n, 1);
            end
        else
            current = strings(n, 1);
        end
        value = string(value);
        if isscalar(value)
            current(idx) = value;
        elseif numel(value) == numel(idx)
            current(idx) = reshape(value, [], 1);
        else
            error("sixgr:truth:InvalidStringAssignment", ...
                "Column %s received %d row indices but %d values.", ...
                char(string(name)), numel(idx), numel(value));
        end
        T.(field) = current;
    end

    function T = setLogicalColumn(T, name, value)
        n = height(T);
        if isscalar(value)
            value = repmat(logical(value), n, 1);
        else
            value = reshape(logical(value), [], 1);
            if numel(value) ~= n
                value = repmat(value(1), n, 1);
            end
        end
        T.(char(name)) = value;
    end

    function T = setNumericColumn(T, name, value, overwrite)
        n = height(T);
        if isscalar(value)
            value = repmat(double(value), n, 1);
        else
            value = reshape(double(value), [], 1);
            if numel(value) ~= n
                value = repmat(value(1), n, 1);
            end
        end
        if ~ismember(string(name), string(T.Properties.VariableNames)) || logical(overwrite)
            T.(char(name)) = value;
            return;
        end
        current = double(T.(char(name)));
        current = reshape(current, [], 1);
        blank = ~isfinite(current);
        current(blank) = value(blank);
        T.(char(name)) = current;
    end

    function writeMirroredTable(layout, fileName, T)
        if ~sixgr.util.persistenceEnabled()
            return;
        end
        controlPath = fullfile(layout.ControlCSVDir, fileName);
        airPath = fullfile(layout.AirInterfaceCSVDir, fileName);
        preserveSchema = strcmpi(string(fileName), "csi_rs_trials.csv");
        if istable(T) && ~isempty(T)
            sixgr.util.csvWriteTable(controlPath, T, "PreserveSchema", preserveSchema);
            sixgr.util.csvWriteTable(airPath, T, "PreserveSchema", preserveSchema);
            return;
        end
        % Zero observations have no primary truth artifact.  The resolved
        % configuration and feature-execution ledger retain intent/status;
        % an empty CSV must never stand in for measured runtime evidence.
        for stalePath = [string(controlPath), string(airPath)]
            if isfile(stalePath)
                delete(stalePath);
            end
        end
    end

    function row = emptyUserPerformanceRow()
        row = struct( ...
            "UEIndex", NaN, "RNTI", NaN, ...
            "DL_FrameCount", NaN, "UL_FrameCount", NaN, ...
            "DL_CoverageStatus", "", "UL_CoverageStatus", "", ...
            "DL_Throughput_Mbps", NaN, "UL_Throughput_Mbps", NaN, ...
            "DL_OfferedThroughput_Mbps", NaN, "UL_OfferedThroughput_Mbps", NaN, ...
            "DL_Goodput_Mbps", NaN, "UL_Goodput_Mbps", NaN, ...
            "DL_BLER", NaN, "UL_BLER", NaN, ...
            "DL_MeanMeasuredSINR_dB", NaN, "UL_MeanMeasuredSINR_dB", NaN, ...
            "UserThroughput_Mbps", NaN, ...
            "UserOfferedThroughput_Mbps", NaN, "UserGoodput_Mbps", NaN, ...
            "DL_HARQFailureRate", NaN, "UL_HARQFailureRate", NaN, ...
            "DL_HARQObservationCount", NaN, "UL_HARQObservationCount", NaN, ...
            "HARQFailureRate", NaN, "HARQObservationCount", NaN);
    end

    function [failureRate, observationCount] = userHARQFailureMetrics(harqTimelineT, ueIdx, direction)
        failureRate = NaN;
        observationCount = NaN;
        if ~(istable(harqTimelineT) && ~isempty(harqTimelineT) && ...
                all(ismember(["UEIndex","CombinedDecodeOK"], string(harqTimelineT.Properties.VariableNames))))
            return;
        end
        mask = abs(double(harqTimelineT.UEIndex) - double(ueIdx)) < 1e-9;
        if ismember("Direction", string(harqTimelineT.Properties.VariableNames)) && strlength(strtrim(string(direction))) > 0
            mask = mask & upper(strtrim(string(harqTimelineT.Direction))) == upper(strtrim(string(direction)));
        end
        if ~any(mask)
            return;
        end
        vals = double(harqTimelineT.CombinedDecodeOK(mask));
        vals = vals(isfinite(vals));
        if isempty(vals)
            return;
        end
        observationCount = double(numel(vals));
        failureRate = mean(1 - vals, "omitnan");
    end

    function [failureRate, observationCount] = combineDirectionalHARQFailureMetrics(dlRate, dlCount, ulRate, ulCount)
        failureRate = NaN;
        observationCount = NaN;
        counts = [double(dlCount) double(ulCount)];
        rates = [double(dlRate) double(ulRate)];
        valid = isfinite(counts) & counts > 0 & isfinite(rates);
        if ~any(valid)
            return;
        end
        observationCount = sum(counts(valid), "omitnan");
        failureRate = sum(rates(valid) .* counts(valid), "omitnan") / max(observationCount, 1);
    end

    function groups = groupPUCCHRowsByPhysicalOccasion(rows)
        groups = cell(0, 1);
        if ~(istable(rows) && ~isempty(rows))
            return;
        end
        dueSlot = double(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
            rows, "ScheduledAbsoluteSlot", nan(height(rows), 1)));
        ueIndex = double(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
            rows, "UEIndex", nan(height(rows), 1)));
        rnti = double(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
            rows, "RNTI", nan(height(rows), 1)));
        servingCell = double(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
            rows, "ServingCell", nan(height(rows), 1)));
        componentCarrier = double(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
            rows, "ComponentCarrier", nan(height(rows), 1)));
        activeULBWP = double(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
            rows, "ActiveULBWP", nan(height(rows), 1)));
        direction = upper(strtrim(string(sixgr.truth.CoupledTruthRuntime. ...
            tableColumnOrDefault(rows, "FeedbackForDirection", repmat("", height(rows), 1)))));
        if any(~isfinite(dueSlot) | ~isfinite(ueIndex) | ~isfinite(rnti) | ...
                ~isfinite(servingCell) | ~isfinite(componentCarrier) | ...
                ~isfinite(activeULBWP) | strlength(direction) == 0)
            error("sixgr:truth:InvalidPUCCHPhysicalOccasionIdentity", ...
                "Every due PUCCH HARQ row must carry slot, UE, RNTI, serving-cell, " + ...
                "component-carrier, active-UL-BWP and feedback-direction identity.");
        end
        keys = compose("slot=%d|ue=%d|rnti=%d|cell=%d|cc=%d|ulbwp=%d|dir=%s", ...
            round(dueSlot), round(ueIndex), round(rnti), round(servingCell), ...
            round(componentCarrier), round(activeULBWP), direction);
        [~, ~, groupIndex] = unique(keys, "stable");
        for groupNumber = 1:max(groupIndex)
            groupRows = rows(groupIndex == groupNumber, :);
            sourceSlot = double(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                groupRows, "SourceSlot", nan(height(groupRows), 1)));
            harqId = double(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                groupRows, "HarqID", nan(height(groupRows), 1)));
            if any(~isfinite(sourceSlot) | ~isfinite(harqId))
                error("sixgr:truth:InvalidPUCCHHARQCodebookIdentity", ...
                    "Every PUCCH HARQ-ACK bit must carry finite source-slot and HARQ-process identity.");
            end
            [~, order] = sortrows([sourceSlot(:), harqId(:)], [1 2]);
            groups{end + 1, 1} = groupRows(order, :); %#ok<AGROW>
        end
    end

    function [dueUEs, dueRNTIs, dueSourceSlots, dueGrantIds, dueEvidenceSources] = collectPUCCHDueIdentityImpl(state, dueSlot)
        dueUEs = [];
        dueRNTIs = [];
        dueSourceSlots = [];
        dueGrantIds = strings(0, 1);
        dueEvidenceSources = strings(0, 1);
        dueSlot = round(double(dueSlot));
        if ~(isfinite(dueSlot) && dueSlot >= 1)
            return;
        end

        pendingFeedback = sixgr.util.structGet(state, "PendingFeedbackTable", table());
        if istable(pendingFeedback) && ~isempty(pendingFeedback)
            for ri = 1:height(pendingFeedback)
                row = pendingFeedback(ri, :);
                rowDueSlot = double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "DueSlot", ...
                    sixgr.truth.CoupledTruthRuntime.rowValue(row, "ScheduledAbsoluteSlot", NaN)));
                if ~(isfinite(rowDueSlot) && abs(rowDueSlot - dueSlot) < 1e-9)
                    continue;
                end
                if logical(sixgr.truth.CoupledTruthRuntime.rowLogical(row, "Processed", false)) || ...
                        logical(sixgr.truth.CoupledTruthRuntime.rowLogical(row, "RightCensored", false))
                    continue;
                end
                deliveryMechanism = lower(strtrim(string( ...
                    sixgr.truth.CoupledTruthRuntime.rowValue(row, "DeliveryMechanism", "pucch"))));
                if deliveryMechanism == "pusch_uci"
                    continue;
                end
                uciType = lower(strtrim(string(sixgr.truth.CoupledTruthRuntime.rowValue(row, "UCIType", "harq_ack"))));
                if strlength(uciType) > 0 && ~contains(uciType, "harq")
                    continue;
                end
                dueUEs(end + 1, 1) = double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "UEIndex", NaN)); %#ok<AGROW>
                dueRNTIs(end + 1, 1) = double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "RNTI", NaN)); %#ok<AGROW>
                dueSourceSlots(end + 1, 1) = double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "SourceSlot", NaN)); %#ok<AGROW>
                dueGrantIds(end + 1, 1) = string(sixgr.truth.CoupledTruthRuntime.rowValue(row, "PUCCHGrantId", "")); %#ok<AGROW>
                dueEvidenceSources(end + 1, 1) = "pending_feedback_table"; %#ok<AGROW>
            end
        end

        pendingCSI = sixgr.util.structGet(state, "PendingCSITable", table());
        if istable(pendingCSI) && ~isempty(pendingCSI)
            for ri = 1:height(pendingCSI)
                row = pendingCSI(ri, :);
                % Only DL CSI is reported by the UE as UCI. UL-direction
                % rows are gNB-side channel knowledge produced from SRS;
                % they are not a PUCCH occasion and therefore cannot
                % collide with, suppress, or reserve a same-slot PUSCH.
                % Missing direction is also insufficient authority to
                % claim a physical UE UCI transmission.
                reportDirection = upper(strtrim(string( ...
                    sixgr.truth.CoupledTruthRuntime.rowValue( ...
                    row, "Direction", ""))));
                if reportDirection ~= "DL"
                    continue;
                end
                rowDueSlot = double(sixgr.truth.CoupledTruthRuntime.rowValue( ...
                    row, "DueSlot", NaN));
                if ~(isfinite(rowDueSlot) && abs(rowDueSlot - dueSlot) < 1e-9) || ...
                        logical(sixgr.truth.CoupledTruthRuntime.rowLogical(row, "Processed", false)) || ...
                        logical(sixgr.truth.CoupledTruthRuntime.rowLogical(row, "RightCensored", false))
                    continue;
                end
                transport = lower(strtrim(string( ...
                    sixgr.truth.CoupledTruthRuntime.rowValue( ...
                    row, "CSIUCITransport", "pucch"))));
                if startsWith(transport, "pusch_")
                    continue;
                end
                dueUEs(end + 1, 1) = double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "UEIndex", NaN)); %#ok<AGROW>
                dueRNTIs(end + 1, 1) = double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "RNTI", NaN)); %#ok<AGROW>
                dueSourceSlots(end + 1, 1) = double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "SourceSlot", NaN)); %#ok<AGROW>
                dueGrantIds(end + 1, 1) = "CSI-" + string(sixgr.truth.CoupledTruthRuntime.rowValue(row, "ReportIdentity", "")); %#ok<AGROW>
                dueEvidenceSources(end + 1, 1) = "pending_csi_table"; %#ok<AGROW>
            end
        end

        pucchGrants = sixgr.util.structGet(state, "PUCCHGrantTraceTable", table());
        if istable(pucchGrants) && ~isempty(pucchGrants)
            for ri = 1:height(pucchGrants)
                row = pucchGrants(ri, :);
                rowDueSlot = double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "ScheduledAbsoluteSlot", ...
                    sixgr.truth.CoupledTruthRuntime.rowValue(row, "Slot", NaN)));
                if ~(isfinite(rowDueSlot) && abs(rowDueSlot - dueSlot) < 1e-9)
                    continue;
                end
                if logical(sixgr.truth.CoupledTruthRuntime.rowLogical(row, "GrantExecutedFlag", false)) || ...
                        logical(sixgr.truth.CoupledTruthRuntime.rowLogical(row, "CanceledAtSweepBoundary", false)) || ...
                        logical(sixgr.truth.CoupledTruthRuntime.rowLogical(row, "RightCensored", false))
                    continue;
                end
                if logical(sixgr.truth.CoupledTruthRuntime.rowLogical(row, "MultiplexedOnPUSCH", false))
                    continue;
                end
                uciType = lower(strtrim(string(sixgr.truth.CoupledTruthRuntime.rowValue(row, "UCIType", "harq_ack"))));
                if strlength(uciType) > 0 && ~contains(uciType, "harq")
                    continue;
                end
                dueUEs(end + 1, 1) = double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "UEIndex", NaN)); %#ok<AGROW>
                dueRNTIs(end + 1, 1) = double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "RNTI", NaN)); %#ok<AGROW>
                dueSourceSlots(end + 1, 1) = double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "SourceSlot", NaN)); %#ok<AGROW>
                dueGrantIds(end + 1, 1) = string(sixgr.truth.CoupledTruthRuntime.rowValue(row, "PUCCHGrantId", "")); %#ok<AGROW>
                dueEvidenceSources(end + 1, 1) = "pucch_grant_trace"; %#ok<AGROW>
            end
        end
    end

    function bits = resolveGrantExpectedUCIBits(grant)
        bits = int8([]);
        if ~(isstruct(grant) && ~isempty(fieldnames(grant)))
            return;
        end
        paths = ["ExpectedUCIBits","MultiplexedUCIBits","HARQACKBits","MultiplexedHARQACKBits"];
        for i = 1:numel(paths)
            raw = sixgr.util.structGet(grant, char(paths(i)), []);
            if isempty(raw)
                continue;
            end
            bits = int8(logical(raw(:)));
            return;
        end
    end

    function writeOptionalFeatureMirroredTable(layout, cfg, featureName, fileName, T)
        % A disabled feature with zero observations has no primary runtime
        % table. Suppress the header-only file instead of making it look
        % like an executed signal; genuine observations are always kept.
        preserveSchema = strcmpi(string(fileName), "csi_rs_trials.csv");
        sixgr.truth.writeOptionalRuntimeFeatureTable(cfg, ...
            string(featureName), ...
            [string(fullfile(layout.ControlCSVDir, fileName)); ...
             string(fullfile(layout.AirInterfaceCSVDir, fileName))], T, ...
            "PreserveSchema", preserveSchema);
    end

    function [state, grantsOut] = multiplexDueHARQACKOnPUSCHImpl(state, grantsIn, dueSlot)
        grantsOut = grantsIn;
        if ~(isstruct(grantsIn) && ~isempty(grantsIn))
            return;
        end
        % A retransmitted UL HARQ grant can inherit the GrantSnapshot from
        % its previous transmission.  UCI-on-PUSCH reservation fields are
        % occasion-local runtime state and must never be replayed with that
        % snapshot.  Preserve an existing binding only when every source
        % row is still pending, belongs to this exact due slot and is bound
        % to this exact PUSCH grant context.  Otherwise clear only the
        % transient HARQ-ACK fields before resolving the current occasion.
        [state, grantsOut] = sixgr.truth.CoupledTruthRuntime. ...
            sanitizePUSCHUCIBindingsForDueSlot(state, grantsOut, dueSlot);
        due = sixgr.truth.CoupledTruthRuntime.collectPUCCHDueHARQACKImpl( ...
            state, dueSlot);
        pendingCSI = sixgr.util.structGet(state, "PendingCSITable", table());
        if istable(pendingCSI) && ~isempty(pendingCSI)
            csiMask = upper(strtrim(string(pendingCSI.Direction))) == "DL" & ...
                ~logical(pendingCSI.Processed) & ...
                ~logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                pendingCSI, "RightCensored", false(height(pendingCSI), 1))) & ...
                abs(double(pendingCSI.DueSlot) - double(dueSlot)) < 1e-9;
            csiTransport = lower(strtrim(string( ...
                sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                pendingCSI, "CSIUCITransport", repmat("pucch", height(pendingCSI), 1)))));
            % A CSI report may have been reserved on a future queued PUSCH
            % before the exact due-slot grant is rebuilt from its frozen
            % PHY snapshot.  The snapshot intentionally does not own
            % occasion-local UCI, so the live grant can arrive here without
            % the transient payload while the pending report still records
            % pusch_bound.  Treat that state as recoverable at the exact due
            % slot and rebuild the typed payload below.  Completed/failed
            % PUSCH deliveries remain ineligible through Processed and the
            % explicit transport filter.
            csiMask = csiMask & (~startsWith(csiTransport, "pusch_") | ...
                csiTransport == "pusch_bound");
            dueCSI = pendingCSI(csiMask, :);
            dueCSIIndices = find(csiMask);
        else
            dueCSI = table();
            dueCSIIndices = zeros(0, 1);
        end
        if isempty(due) && isempty(dueCSI)
            return;
        end

        assignedGrantIds = strings(0, 1);
        assignedCSIReportIds = strings(0, 1);
        for gi = 1:numel(grantsOut)
            ueIdx = double(sixgr.util.structGet(grantsOut(gi), "UEIndex", NaN));
            rnti = double(sixgr.util.structGet(grantsOut(gi), "RNTI", NaN));
            match = false(numel(due), 1);
            for di = 1:numel(due)
                dueUE = double(sixgr.util.structGet(due(di), "UEIndex", NaN));
                dueRNTI = double(sixgr.util.structGet(due(di), "RNTI", NaN));
                match(di) = (isfinite(ueIdx) && isfinite(dueUE) && ueIdx == dueUE) || ...
                    (isfinite(rnti) && isfinite(dueRNTI) && rnti == dueRNTI);
            end
            matched = due(match);
            csiMatch = false(height(dueCSI), 1);
            for ci = 1:height(dueCSI)
                dueUE = double(dueCSI.UEIndex(ci));
                dueRNTI = double(dueCSI.RNTI(ci));
                csiMatch(ci) = (isfinite(ueIdx) && isfinite(dueUE) && ueIdx == dueUE) || ...
                    (isfinite(rnti) && isfinite(dueRNTI) && rnti == dueRNTI);
            end
            matchedCSI = dueCSI(csiMatch, :);
            matchedCSIIndices = dueCSIIndices(csiMatch);
            if height(matchedCSI) > 1
                error("sixgr:truth:AmbiguousPUSCHCSIReservation", ...
                    ["A single PUSCH occasion cannot consume more than one " + ...
                     "unmerged CSI report for the same UE and due slot."]);
            end
            if isempty(matched) && isempty(matchedCSI)
                continue;
            end
            ackBits = int8([]);
            sourceSlots = zeros(0, 1);
            harqIds = zeros(0, 1);
            grantIds = strings(0, 1);
            if ~isempty(matched)
                sourceSlots = arrayfun(@(x) double(x.SourceSlot), matched(:));
                harqIds = arrayfun(@(x) double(x.HarqID), matched(:));
                [~, order] = sortrows([sourceSlots(:) harqIds(:)], [1 2]);
                matched = matched(order);
                sourceSlots = sourceSlots(order);
                harqIds = harqIds(order);
                grantIds = string({matched.PUCCHGrantId}).';
                if any(strlength(strtrim(grantIds)) == 0) || ...
                        any(ismember(grantIds, assignedGrantIds))
                    error("sixgr:truth:InvalidPUSCHHARQACKReservation", ...
                        "Each pending DL HARQ feedback row must bind exactly once to a PUSCH UCI payload.");
                end
                assignedGrantIds = [assignedGrantIds; grantIds]; %#ok<AGROW>
                ackBits = int8(arrayfun(@(x) logical(x.AckBit), matched(:)));
            end
            csiPart1 = int8([]);
            csiPart2 = int8([]);
            csiReportIdentity = "";
            if ~isempty(matchedCSI)
                csiPart1 = int8(sixgr.runtime.RawCSVArrayCodec.decode( ...
                    string(matchedCSI.CSIPart1BitsToken(1))));
                csiPart2 = int8(sixgr.runtime.RawCSVArrayCodec.decode( ...
                    string(matchedCSI.CSIPart2BitsToken(1))));
                if numel(csiPart1) ~= double(matchedCSI.CSIPart1BitCount(1)) || ...
                        numel(csiPart2) ~= double(matchedCSI.CSIPart2BitCount(1))
                    error("sixgr:truth:InvalidPUSCHCSIReservation", ...
                        "Persisted CSI UCI bit counts disagree with the typed payload tokens.");
                end
                csiReportIdentity = string(matchedCSI.ReportIdentity(1));
                if any(assignedCSIReportIds == csiReportIdentity)
                    error("sixgr:truth:DuplicatePUSCHCSIReservation", ...
                        "CSI report %s cannot bind to more than one PUSCH occasion.", ...
                        char(csiReportIdentity));
                end
                assignedCSIReportIds(end + 1, 1) = csiReportIdentity; %#ok<AGROW>
            end
            contextId = string(sixgr.util.structGet(grantsOut(gi), ...
                "GrantContextId", sixgr.util.structGet(grantsOut(gi), ...
                "PHYGrant.GrantContextId", "")));
            if strlength(strtrim(contextId)) == 0
                error("sixgr:truth:MissingPUSCHUCIGrantContext", ...
                    "UCI-on-PUSCH requires the exact frozen PUSCH grant context identity.");
            end
            typedPayload = sixgr.phy.ul.pusch.PUSCHUCIPayload( ...
                "HARQACK", ackBits(:), "CSIPart1", csiPart1(:), ...
                "CSIPart2", csiPart2(:), ...
                "CSIPart2DependsOnPart1", ~isempty(csiPart2));
            grantsOut(gi).ExpectedUCIPayload = typedPayload;
            grantsOut(gi).ExpectedUCIBits = ackBits(:);
            grantsOut(gi).MultiplexedHARQACKBits = ackBits(:);
            grantsOut(gi).UCIOnPUSCHApplied = true;
            if ~isempty(csiPart1)
                grantsOut(gi).UCIOnPUSCHSource = ...
                    "pending_dl_harq_and_or_csi_nrULSCHMultiplex";
                grantsOut(gi).PUCCHCollisionPolicy = ...
                    "harq_csi_multiplexed_on_pusch";
            else
                grantsOut(gi).UCIOnPUSCHSource = ...
                    "pending_dl_harq_ack_nrULSCHMultiplex";
                grantsOut(gi).PUCCHCollisionPolicy = ...
                    "harq_ack_multiplexed_on_pusch";
            end
            grantsOut(gi).UCIOnPUSCHFeedbackGrantIds = char(strjoin(grantIds, "|"));
            grantsOut(gi).UCIOnPUSCHFeedbackSourceSlots = double(sourceSlots(:).');
            grantsOut(gi).UCIOnPUSCHFeedbackHARQIds = double(harqIds(:).');
            grantsOut(gi).UCIOnPUSCHFeedbackBitCount = double(numel(ackBits));
            grantsOut(gi).UCIOnPUSCHEvidenceSource = ...
                "pending_feedback_table_reserved_after_pdcch_grant_binding";
            grantsOut(gi).UCIOnPUSCHCSIReportIdentity = char(csiReportIdentity);
            grantsOut(gi).UCIOnPUSCHCSIPart1BitCount = double(numel(csiPart1));
            grantsOut(gi).UCIOnPUSCHCSIPart2BitCount = double(numel(csiPart2));

            if ~isempty(grantIds)
                state = sixgr.truth.CoupledTruthRuntime. ...
                    markFeedbackRowsReservedForPUSCH(state, grantIds, contextId);
            end
            if ~isempty(matchedCSIIndices)
                state.PendingCSITable = sixgr.truth.CoupledTruthRuntime. ...
                    setStringValueAt(state.PendingCSITable, ...
                    "CSIUCITransport", matchedCSIIndices, "pusch_bound");
                state.PendingCSITable.CSIUCIMultiplexedOnPUSCH(matchedCSIIndices) = true;
                state.PendingCSITable = sixgr.truth.CoupledTruthRuntime. ...
                    setStringValueAt(state.PendingCSITable, ...
                    "CSIUCIPUSCHGrantContextId", matchedCSIIndices, contextId);
                state.PendingCSITable = sixgr.truth.CoupledTruthRuntime. ...
                    setStringValueAt(state.PendingCSITable, ...
                    "CSIUCIDeliveryReason", matchedCSIIndices, ...
                    "typed_csi_reserved_on_frozen_pusch_grant");
            end
        end
    end

    function [state, grantsOut] = sanitizePUSCHUCIBindingsForDueSlot(state, grantsIn, dueSlot)
        grantsOut = grantsIn;
        dueSlot = round(double(dueSlot));
        pending = sixgr.util.structGet(state, "PendingFeedbackTable", table());
        pendingCSI = sixgr.util.structGet(state, "PendingCSITable", table());
        traceT = sixgr.util.structGet(state, "PUCCHGrantTraceTable", table());
        for gi = 1:numel(grantsOut)
            contextId = string(sixgr.util.structGet(grantsOut(gi), ...
                "GrantContextId", sixgr.util.structGet(grantsOut(gi), ...
                "PHYGrant.GrantContextId", "")));
            grantIdsToken = string(sixgr.util.structGet(grantsOut(gi), ...
                "UCIOnPUSCHFeedbackGrantIds", ""));
            csiReportIdentity = string(sixgr.util.structGet(grantsOut(gi), ...
                "UCIOnPUSCHCSIReportIdentity", ""));

            % The pending HARQ/CSI ledgers, not a reconstructed grant
            % snapshot, are the authority for occasion-local UCI.  A queued
            % grant can legitimately acquire CSI first and HARQ-ACK later.
            % In that case its live transient fields are only a strict subset
            % of the rows already bound to the exact grant context.  Discover
            % that complete lineage before deciding whether the binding can
            % be reused.  Any exact bound lineage is released and rebuilt
            % below so a partial CSI-only or HARQ-only payload can never be
            % accepted at the due-slot receiver boundary.
            ledgerGrantIds = strings(0, 1);
            if istable(pending) && ~isempty(pending) && ...
                    all(ismember(["PUCCHGrantId","DueSlot"], ...
                    string(pending.Properties.VariableNames))) && ...
                    strlength(strtrim(contextId)) > 0
                processed = logical(sixgr.truth.CoupledTruthRuntime. ...
                    tableColumnOrDefault(pending, "Processed", ...
                    false(height(pending), 1)));
                censored = logical(sixgr.truth.CoupledTruthRuntime. ...
                    tableColumnOrDefault(pending, "RightCensored", ...
                    false(height(pending), 1)));
                mechanism = lower(strtrim(string( ...
                    sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                    pending, "DeliveryMechanism", ...
                    repmat("pucch", height(pending), 1)))));
                boundContext = string(sixgr.truth.CoupledTruthRuntime. ...
                    tableColumnOrDefault(pending, "PUSCHGrantContextId", ...
                    strings(height(pending), 1)));
                ledgerMask = ~processed & ~censored & ...
                    abs(double(pending.DueSlot) - dueSlot) < 1e-9 & ...
                    mechanism == "pusch_uci" & boundContext == contextId;
                ledgerGrantIds = unique(string( ...
                    pending.PUCCHGrantId(ledgerMask)), "stable");
                ledgerGrantIds = ledgerGrantIds( ...
                    strlength(strtrim(ledgerGrantIds)) > 0);
            end
            declaredGrantIds = split(grantIdsToken, "|");
            declaredGrantIds = declaredGrantIds( ...
                strlength(strtrim(declaredGrantIds)) > 0);
            grantIdsForRelease = unique( ...
                [declaredGrantIds(:); ledgerGrantIds(:)], "stable");
            if ~isempty(grantIdsForRelease)
                grantIdsToken = strjoin(grantIdsForRelease, "|");
            end

            ledgerCSIReportIds = strings(0, 1);
            if istable(pendingCSI) && ~isempty(pendingCSI) && ...
                    all(ismember(["ReportIdentity","DueSlot"], ...
                    string(pendingCSI.Properties.VariableNames))) && ...
                    strlength(strtrim(contextId)) > 0
                processedCSI = logical(sixgr.truth.CoupledTruthRuntime. ...
                    tableColumnOrDefault(pendingCSI, "Processed", ...
                    false(height(pendingCSI), 1)));
                censoredCSI = logical(sixgr.truth.CoupledTruthRuntime. ...
                    tableColumnOrDefault(pendingCSI, "RightCensored", ...
                    false(height(pendingCSI), 1)));
                csiTransport = lower(strtrim(string( ...
                    sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                    pendingCSI, "CSIUCITransport", ...
                    repmat("pucch", height(pendingCSI), 1)))));
                csiContext = string(sixgr.truth.CoupledTruthRuntime. ...
                    tableColumnOrDefault(pendingCSI, ...
                    "CSIUCIPUSCHGrantContextId", ...
                    strings(height(pendingCSI), 1)));
                csiLedgerMask = ~processedCSI & ~censoredCSI & ...
                    abs(double(pendingCSI.DueSlot) - dueSlot) < 1e-9 & ...
                    csiTransport == "pusch_bound" & csiContext == contextId;
                ledgerCSIReportIds = unique(string( ...
                    pendingCSI.ReportIdentity(csiLedgerMask)), "stable");
                ledgerCSIReportIds = ledgerCSIReportIds( ...
                    strlength(strtrim(ledgerCSIReportIds)) > 0);
            end
            declaredCSIReportIds = csiReportIdentity( ...
                strlength(strtrim(csiReportIdentity)) > 0);
            csiIdsForRelease = unique( ...
                [declaredCSIReportIds(:); ledgerCSIReportIds(:)], "stable");
            if numel(csiIdsForRelease) > 1
                error("sixgr:truth:AmbiguousPUSCHCSIReservation", ...
                    ["A single exact PUSCH grant context cannot own more " + ...
                     "than one unmerged CSI report at the same due slot."]);
            elseif ~isempty(csiIdsForRelease)
                csiReportIdentity = csiIdsForRelease(1);
            end
            authoritativeBoundLineagePresent = ...
                ~isempty(ledgerGrantIds) || ~isempty(ledgerCSIReportIds);
            hasHARQBinding = isscalar(grantIdsToken) && ...
                strlength(strtrim(grantIdsToken)) > 0;
            hasCSIBinding = isscalar(csiReportIdentity) && ...
                strlength(strtrim(csiReportIdentity)) > 0;
            hasTypedPayload = isa(sixgr.util.structGet(grantsOut(gi), ...
                "ExpectedUCIPayload", []), ...
                "sixgr.phy.ul.pusch.PUSCHUCIPayload");
            if ~hasHARQBinding && ~hasCSIBinding && ~hasTypedPayload
                continue;
            end
            bindingValid = isfinite(dueSlot) && dueSlot >= 1 && ...
                strlength(strtrim(contextId)) > 0 && ...
                ~authoritativeBoundLineagePresent;
            if hasHARQBinding && bindingValid
                grantIds = split(grantIdsToken, "|");
                grantIds = grantIds(strlength(strtrim(grantIds)) > 0);
                bindingValid = ~isempty(grantIds) && ...
                    numel(unique(grantIds)) == numel(grantIds) && ...
                    istable(pending) && ~isempty(pending) && ...
                    ismember("PUCCHGrantId", string(pending.Properties.VariableNames)) && ...
                    istable(traceT) && ~isempty(traceT) && ...
                    ismember("PUCCHGrantId", string(traceT.Properties.VariableNames));
                for bitIdx = 1:numel(grantIds)
                    if ~bindingValid
                        break;
                    end
                    pendingMask = string(pending.PUCCHGrantId) == grantIds(bitIdx) & ...
                        ~logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                        pending, "Processed", false(height(pending), 1))) & ...
                        ~logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                        pending, "RightCensored", false(height(pending), 1)));
                    traceMask = string(traceT.PUCCHGrantId) == grantIds(bitIdx) & ...
                        logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                        traceT, "MultiplexedOnPUSCH", false(height(traceT), 1))) & ...
                        ~logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                        traceT, "GrantExecutedFlag", false(height(traceT), 1))) & ...
                        ~logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                        traceT, "RightCensored", false(height(traceT), 1)));
                    if nnz(pendingMask) ~= 1 || nnz(traceMask) ~= 1
                        bindingValid = false;
                        break;
                    end
                    pendingIdx = find(pendingMask, 1);
                    traceIdx = find(traceMask, 1);
                    pendingDueSlot = double(sixgr.truth.CoupledTruthRuntime.rowValue( ...
                        pending(pendingIdx, :), "DueSlot", NaN));
                    pendingMechanism = lower(strtrim(string( ...
                        sixgr.truth.CoupledTruthRuntime.rowValue( ...
                        pending(pendingIdx, :), "DeliveryMechanism", ""))));
                    pendingContextId = string(sixgr.truth.CoupledTruthRuntime.rowValue( ...
                        pending(pendingIdx, :), "PUSCHGrantContextId", ""));
                    traceDueSlot = double(sixgr.truth.CoupledTruthRuntime.rowValue( ...
                        traceT(traceIdx, :), "ScheduledAbsoluteSlot", NaN));
                    traceContextId = string(sixgr.truth.CoupledTruthRuntime.rowValue( ...
                        traceT(traceIdx, :), "PUSCHGrantContextId", ""));
                    if pendingDueSlot ~= dueSlot || traceDueSlot ~= dueSlot || ...
                            pendingMechanism ~= "pusch_uci" || ...
                            pendingContextId ~= contextId || traceContextId ~= contextId
                        bindingValid = false;
                        break;
                    end
                end
            end
            if hasCSIBinding && bindingValid
                bindingValid = istable(pendingCSI) && ~isempty(pendingCSI) && ...
                    all(ismember(["ReportIdentity","DueSlot"], ...
                    string(pendingCSI.Properties.VariableNames)));
                if bindingValid
                    csiMask = string(pendingCSI.ReportIdentity) == csiReportIdentity & ...
                        ~logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                        pendingCSI, "Processed", false(height(pendingCSI), 1))) & ...
                        ~logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                        pendingCSI, "RightCensored", false(height(pendingCSI), 1)));
                    if nnz(csiMask) ~= 1
                        bindingValid = false;
                    else
                        csiIdx = find(csiMask, 1);
                        csiDueSlot = double(pendingCSI.DueSlot(csiIdx));
                        csiTransport = lower(strtrim(string( ...
                            sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                            pendingCSI, "CSIUCITransport", ...
                            repmat("", height(pendingCSI), 1)))));
                        csiContext = string( ...
                            sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                            pendingCSI, "CSIUCIPUSCHGrantContextId", ...
                            strings(height(pendingCSI), 1)));
                        csiMultiplexed = logical( ...
                            sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                            pendingCSI, "CSIUCIMultiplexedOnPUSCH", ...
                            false(height(pendingCSI), 1)));
                        bindingValid = csiDueSlot == dueSlot && ...
                            csiTransport(csiIdx) == "pusch_bound" && ...
                            csiMultiplexed(csiIdx) && ...
                            csiContext(csiIdx) == contextId;
                    end
                end
            end
            % A typed payload without explicit report/grant lineage is not
            % reusable occasion state.  This catches stale snapshots that
            % predate the typed CSI/HARQ identity fields.
            if hasTypedPayload && ~hasHARQBinding && ~hasCSIBinding
                bindingValid = false;
            end
            if bindingValid
                continue;
            end
            % Occasion-local UCI state spans the live grant, the pending
            % HARQ/CSI ledgers and the PUCCH trace.  Clearing only the grant
            % leaves the source rows marked pusch_uci/pusch_bound, making
            % them ineligible for the exact due-slot rebuild below.  Release
            % every still-pending row by its immutable report/grant identity
            % before clearing the stale payload so the current frozen grant
            % can atomically rebind the complete UCI payload.
            state = sixgr.truth.CoupledTruthRuntime. ...
                releaseInvalidPUSCHUCIBinding( ...
                state, grantIdsToken, csiReportIdentity);
            grantsOut(gi).ExpectedUCIPayload = [];
            grantsOut(gi).ExpectedUCIBits = int8([]);
            grantsOut(gi).MultiplexedHARQACKBits = int8([]);
            grantsOut(gi).UCIOnPUSCHApplied = false;
            grantsOut(gi).UCIOnPUSCHSource = "";
            grantsOut(gi).PUCCHCollisionPolicy = "";
            grantsOut(gi).UCIOnPUSCHFeedbackGrantIds = "";
            grantsOut(gi).UCIOnPUSCHFeedbackSourceSlots = [];
            grantsOut(gi).UCIOnPUSCHFeedbackHARQIds = [];
            grantsOut(gi).UCIOnPUSCHFeedbackBitCount = 0;
            grantsOut(gi).UCIOnPUSCHEvidenceSource = "";
            grantsOut(gi).UCIOnPUSCHCSIReportIdentity = "";
            grantsOut(gi).UCIOnPUSCHCSIPart1BitCount = 0;
            grantsOut(gi).UCIOnPUSCHCSIPart2BitCount = 0;
        end
    end

    function state = releaseInvalidPUSCHUCIBinding( ...
            state, grantIdsToken, csiReportIdentity)
        grantIds = split(string(grantIdsToken), "|");
        grantIds = unique(grantIds(strlength(strtrim(grantIds)) > 0), "stable");
        pending = sixgr.util.structGet(state, "PendingFeedbackTable", table());
        if istable(pending) && ~isempty(pending) && ~isempty(grantIds) && ...
                ismember("PUCCHGrantId", string(pending.Properties.VariableNames))
            processed = logical(sixgr.truth.CoupledTruthRuntime. ...
                tableColumnOrDefault(pending, "Processed", ...
                false(height(pending), 1)));
            censored = logical(sixgr.truth.CoupledTruthRuntime. ...
                tableColumnOrDefault(pending, "RightCensored", ...
                false(height(pending), 1)));
            releaseMask = ismember(string(pending.PUCCHGrantId), grantIds) & ...
                ~processed & ~censored;
            if any(releaseMask)
                pending = sixgr.truth.CoupledTruthRuntime.setStringValueAt( ...
                    pending, "DeliveryMechanism", find(releaseMask), "pucch");
                pending = sixgr.truth.CoupledTruthRuntime.setStringValueAt( ...
                    pending, "PUSCHGrantContextId", find(releaseMask), "");
                if ismember("MultiplexedBitIndex", ...
                        string(pending.Properties.VariableNames))
                    pending.MultiplexedBitIndex(releaseMask) = NaN;
                end
            end
            state.PendingFeedbackTable = pending;
        end

        traceT = sixgr.util.structGet(state, "PUCCHGrantTraceTable", table());
        if istable(traceT) && ~isempty(traceT) && ~isempty(grantIds) && ...
                ismember("PUCCHGrantId", string(traceT.Properties.VariableNames))
            executed = logical(sixgr.truth.CoupledTruthRuntime. ...
                tableColumnOrDefault(traceT, "GrantExecutedFlag", ...
                false(height(traceT), 1)));
            censored = logical(sixgr.truth.CoupledTruthRuntime. ...
                tableColumnOrDefault(traceT, "RightCensored", ...
                false(height(traceT), 1)));
            releaseMask = ismember(string(traceT.PUCCHGrantId), grantIds) & ...
                ~executed & ~censored;
            if any(releaseMask)
                traceT.MultiplexedOnPUSCH(releaseMask) = false;
                traceT = sixgr.truth.CoupledTruthRuntime.setStringValueAt( ...
                    traceT, "PUSCHGrantContextId", find(releaseMask), "");
                if ismember("MultiplexedBitIndex", ...
                        string(traceT.Properties.VariableNames))
                    traceT.MultiplexedBitIndex(releaseMask) = NaN;
                end
                traceT = sixgr.truth.CoupledTruthRuntime.setStringValueAt( ...
                    traceT, "PUCCHGrantState", find(releaseMask), ...
                    "scheduled_pending_execution");
                traceT = sixgr.truth.CoupledTruthRuntime.setStringValueAt( ...
                    traceT, "Status", find(releaseMask), "PENDING");
                traceT = sixgr.truth.CoupledTruthRuntime.setStringValueAt( ...
                    traceT, "Notes", find(releaseMask), ...
                    "Stale PUSCH-UCI binding released before exact due-slot reconciliation.");
            end
            state.PUCCHGrantTraceTable = traceT;
        end

        csiReportIdentity = string(csiReportIdentity);
        pendingCSI = sixgr.util.structGet(state, "PendingCSITable", table());
        if istable(pendingCSI) && ~isempty(pendingCSI) && ...
                isscalar(csiReportIdentity) && ...
                strlength(strtrim(csiReportIdentity)) > 0 && ...
                ismember("ReportIdentity", ...
                string(pendingCSI.Properties.VariableNames))
            processed = logical(sixgr.truth.CoupledTruthRuntime. ...
                tableColumnOrDefault(pendingCSI, "Processed", ...
                false(height(pendingCSI), 1)));
            censored = logical(sixgr.truth.CoupledTruthRuntime. ...
                tableColumnOrDefault(pendingCSI, "RightCensored", ...
                false(height(pendingCSI), 1)));
            releaseMask = string(pendingCSI.ReportIdentity) == ...
                csiReportIdentity & ~processed & ~censored;
            if any(releaseMask)
                pendingCSI = sixgr.truth.CoupledTruthRuntime. ...
                    setStringValueAt(pendingCSI, "CSIUCITransport", ...
                    find(releaseMask), "pucch");
                pendingCSI.CSIUCIMultiplexedOnPUSCH(releaseMask) = false;
                pendingCSI = sixgr.truth.CoupledTruthRuntime. ...
                    setStringValueAt(pendingCSI, ...
                    "CSIUCIPUSCHGrantContextId", find(releaseMask), "");
                pendingCSI = sixgr.truth.CoupledTruthRuntime. ...
                    setStringValueAt(pendingCSI, "CSIUCIDeliveryReason", ...
                    find(releaseMask), ...
                    "stale_pusch_binding_released_for_exact_due_slot_reconciliation");
            end
            state.PendingCSITable = pendingCSI;
        end
    end

    function [state, grantsOut, blockedT] = reconcileQueuedPUSCHAfterDLFeedbackImpl( ...
            state, grantsIn, uciOnPUSCHAvailable)
        grantsOut = repmat(struct(), 0, 1);
        blockedT = struct2table(repmat( ...
            sixgr.truth.CoupledTruthRuntime.emptyPUSCHPUCCHCollisionRow(), 0, 1));
        if ~(isstruct(grantsIn) && ~isempty(grantsIn))
            return;
        end
        uciOnPUSCHAvailable = logical(uciOnPUSCHAvailable);
        dueSlots = arrayfun(@(g) double(sixgr.util.structGet(g, ...
            "ScheduledAbsoluteSlot", sixgr.util.structGet(g, "Slot", NaN))), ...
            grantsIn(:));
        if any(~isfinite(dueSlots) | dueSlots < 1 | ...
                abs(dueSlots - round(dueSlots)) > 1e-9)
            error("sixgr:truth:InvalidQueuedPUSCHDueSlot", ...
                "Every queued PUSCH grant must carry a finite integer ScheduledAbsoluteSlot before late HARQ-ACK reconciliation.");
        end

        uniqueDueSlots = unique(round(dueSlots), "stable");
        for slotIdx = 1:numel(uniqueDueSlots)
            dueSlot = uniqueDueSlots(slotIdx);
            slotGrants = grantsIn(round(dueSlots) == dueSlot);
            if uciOnPUSCHAvailable
                [state, slotGrants] = sixgr.truth.CoupledTruthRuntime. ...
                    multiplexDueHARQACKOnPUSCHImpl(state, slotGrants, dueSlot);
            end
            [slotGrants, slotBlockedT] = sixgr.truth.CoupledTruthRuntime. ...
                excludeULGrantsCollidingWithPUCCHImpl(state, slotGrants, dueSlot);
            if ~isempty(slotGrants)
                if isempty(grantsOut)
                    grantsOut = slotGrants;
                else
                    [grantsOut, slotGrants] = sixgr.truth.CoupledTruthRuntime. ...
                        harmonizeStructArray(grantsOut, slotGrants);
                    grantsOut = vertcat(grantsOut, slotGrants);
                end
            end
            if istable(slotBlockedT) && ~isempty(slotBlockedT)
                blockedT = sixgr.truth.CoupledTruthRuntime. ...
                    appendCompatTable(blockedT, slotBlockedT);
            end
        end
    end

    function state = markFeedbackRowsReservedForPUSCH(state, grantIds, contextId)
        grantIds = string(grantIds(:));
        pending = sixgr.util.structGet(state, "PendingFeedbackTable", table());
        if istable(pending) && ~isempty(pending) && ...
                ismember("PUCCHGrantId", string(pending.Properties.VariableNames))
            if ~ismember("DeliveryMechanism", string(pending.Properties.VariableNames))
                pending.DeliveryMechanism = repmat("pucch", height(pending), 1);
            end
            if ~ismember("PUSCHGrantContextId", string(pending.Properties.VariableNames))
                pending.PUSCHGrantContextId = strings(height(pending), 1);
            end
            if ~ismember("MultiplexedBitIndex", string(pending.Properties.VariableNames))
                pending.MultiplexedBitIndex = nan(height(pending), 1);
            end
            for bitIdx = 1:numel(grantIds)
                rightCensored = logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                    pending, "RightCensored", false(height(pending), 1)));
                mask = string(pending.PUCCHGrantId) == grantIds(bitIdx) & ...
                    ~logical(pending.Processed) & ~rightCensored;
                if nnz(mask) ~= 1
                    error("sixgr:truth:InvalidPUSCHHARQACKReservation", ...
                        "PUSCH UCI reservation requires one unprocessed pending row for grant %s.", ...
                        char(grantIds(bitIdx)));
                end
                pending.DeliveryMechanism(mask) = "pusch_uci";
                pending.PUSCHGrantContextId(mask) = contextId;
                pending.MultiplexedBitIndex(mask) = bitIdx;
            end
            state.PendingFeedbackTable = pending;
        end

        traceT = sixgr.util.structGet(state, "PUCCHGrantTraceTable", table());
        if istable(traceT) && ~isempty(traceT) && ...
                ismember("PUCCHGrantId", string(traceT.Properties.VariableNames))
            if ~ismember("MultiplexedOnPUSCH", string(traceT.Properties.VariableNames))
                traceT.MultiplexedOnPUSCH = false(height(traceT), 1);
            end
            if ~ismember("PUSCHGrantContextId", string(traceT.Properties.VariableNames))
                traceT.PUSCHGrantContextId = strings(height(traceT), 1);
            end
            if ~ismember("MultiplexedBitIndex", string(traceT.Properties.VariableNames))
                traceT.MultiplexedBitIndex = nan(height(traceT), 1);
            end
            if ~ismember("PUSCHUCIDecodeOk", string(traceT.Properties.VariableNames))
                traceT.PUSCHUCIDecodeOk = false(height(traceT), 1);
            end
            for bitIdx = 1:numel(grantIds)
                rightCensored = logical(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
                    traceT, "RightCensored", false(height(traceT), 1)));
                mask = string(traceT.PUCCHGrantId) == grantIds(bitIdx) & ...
                    ~logical(traceT.GrantExecutedFlag) & ~rightCensored;
                if nnz(mask) ~= 1
                    error("sixgr:truth:InvalidPUSCHHARQACKReservation", ...
                        "PUSCH UCI reservation requires one unexecuted control-grant row for grant %s.", ...
                        char(grantIds(bitIdx)));
                end
                traceT.MultiplexedOnPUSCH(mask) = true;
                traceT.PUSCHGrantContextId(mask) = contextId;
                traceT.MultiplexedBitIndex(mask) = bitIdx;
                traceT.PUCCHGrantState(mask) = "transferred_to_pusch_uci";
                traceT.Status(mask) = "PENDING_PUSCH_UCI";
                traceT.Notes(mask) = "Scheduled PUCCH HARQ-ACK transferred to the same-UE PUSCH UCI payload before the due slot.";
            end
            state.PUCCHGrantTraceTable = traceT;
        end
    end

    function state = consumeDecodedPUSCHHARQACK(state, harqOut)
        % Apply DL HARQ-ACK only from the UCI bits actually decoded by the
        % current PUSCH receiver.  Expected bits remain an oracle used to
        % score false ACK/NACK; they are never substituted for missing or
        % failed receiver output.
        if ~(isstruct(harqOut) && ~isempty(fieldnames(harqOut)))
            return;
        end
        grant = sixgr.util.structGet(harqOut, "GrantSnapshot", ...
            sixgr.util.structGet(harqOut, "Context.GrantSnapshot", struct()));
        expectedBits = int8(sixgr.util.structGet(harqOut, ...
            "ExpectedHARQACKBits", sixgr.util.structGet(grant, ...
            "ExpectedUCIBits", int8([]))));
        expectedBits = expectedBits(:);
        if isempty(expectedBits)
            return;
        end
        if any(~ismember(double(expectedBits), [0 1]))
            error("sixgr:truth:InvalidPUSCHHARQACKEvidence", ...
                "Expected PUSCH HARQ-ACK mapping contains non-binary values.");
        end

        grantIdsToken = string(sixgr.util.structGet(grant, ...
            "UCIOnPUSCHFeedbackGrantIds", ""));
        if ~(isscalar(grantIdsToken) && strlength(strtrim(grantIdsToken)) > 0)
            error("sixgr:truth:MissingPUSCHHARQACKBinding", ...
                "Decoded PUSCH HARQ-ACK requires exact source PUCCH-grant " + ...
                "identities; configured/expected bits cannot stand in for that binding.");
        end
        grantIds = split(grantIdsToken, "|");
        grantIds = grantIds(strlength(strtrim(grantIds)) > 0);
        sourceSlots = double(sixgr.util.structGet(grant, ...
            "UCIOnPUSCHFeedbackSourceSlots", []));
        harqIds = double(sixgr.util.structGet(grant, ...
            "UCIOnPUSCHFeedbackHARQIds", []));
        sourceSlots = sourceSlots(:);
        harqIds = harqIds(:);
        nBits = numel(expectedBits);
        if numel(grantIds) ~= nBits || numel(sourceSlots) ~= nBits || ...
                numel(harqIds) ~= nBits || numel(unique(grantIds)) ~= nBits
            error("sixgr:truth:InvalidPUSCHHARQACKBinding", ...
                "PUSCH HARQ-ACK requires a one-to-one grant/source-slot/" + ...
                "HARQ-process binding for every decoded control bit.");
        end

        decodedBits = int8(sixgr.util.structGet(harqOut, ...
            "DecodedHARQACKBits", int8([])));
        decodedBits = decodedBits(:);
        decodeStatus = lower(strtrim(string(sixgr.util.structGet(harqOut, ...
            "HARQACKDecodeStatus", ""))));
        decodedVectorAvailable = numel(decodedBits) == nBits && ...
            all(ismember(double(decodedBits), [0 1])) && ...
            startsWith(decodeStatus, "decoded");
        if decodedVectorAvailable
            observedBits = decodedBits;
        else
            % DTX/missing UCI is a NACK at the HARQ entity.  This is an
            % observed failure outcome, not a replacement with oracle bits.
            observedBits = zeros(nBits, 1, "int8");
        end
        computedContentMatch = decodedVectorAvailable && ...
            isequal(decodedBits, expectedBits);
        reportedContentMatch = logical(sixgr.util.structGet(harqOut, ...
            "HARQACKContentMatch", computedContentMatch));
        if decodedVectorAvailable && reportedContentMatch ~= computedContentMatch
            error("sixgr:truth:InconsistentPUSCHHARQACKEvidence", ...
                "PUSCH receiver content-match status disagrees with its decoded HARQ-ACK vector.");
        end

        pending = sixgr.util.structGet(state, "PendingFeedbackTable", table());
        traceT = sixgr.util.structGet(state, "PUCCHGrantTraceTable", table());
        if ~(istable(pending) && ~isempty(pending) && ...
                ismember("PUCCHGrantId", string(pending.Properties.VariableNames)) && ...
                istable(traceT) && ~isempty(traceT) && ...
                ismember("PUCCHGrantId", string(traceT.Properties.VariableNames)))
            error("sixgr:truth:MissingPUSCHHARQACKRuntimeRows", ...
                "PUSCH HARQ-ACK cannot update DL HARQ without its reserved pending and control-grant rows.");
        end
        currentSlot = double(sixgr.util.structGet(state, "CurrentSlot", NaN));
        puschContextId = string(sixgr.util.structGet(grant, "GrantContextId", ...
            sixgr.util.structGet(grant, "PHYGrant.GrantContextId", "")));
        harq = state.DLHarq;
        buffers = state.DLCombinedLLR;

        for bitIdx = 1:nBits
            pendingMask = string(pending.PUCCHGrantId) == grantIds(bitIdx) & ...
                ~logical(pending.Processed);
            traceMask = string(traceT.PUCCHGrantId) == grantIds(bitIdx) & ...
                logical(traceT.MultiplexedOnPUSCH) & ...
                ~logical(traceT.GrantExecutedFlag);
            if nnz(pendingMask) ~= 1 || nnz(traceMask) ~= 1
                error("sixgr:truth:InvalidPUSCHHARQACKRuntimeRows", ...
                    "PUSCH HARQ-ACK grant %s must bind one pending row and one transferred control-grant row.", ...
                    char(grantIds(bitIdx)));
            end
            pendingIdx = find(pendingMask, 1);
            traceIdx = find(traceMask, 1);
            pendingRow = pending(pendingIdx, :);
            rowSourceSlot = double(sixgr.truth.CoupledTruthRuntime.rowValue( ...
                pendingRow, "SourceSlot", NaN));
            rowHarqId = double(sixgr.truth.CoupledTruthRuntime.rowValue( ...
                pendingRow, "HarqID", NaN));
            rowDueSlot = double(sixgr.truth.CoupledTruthRuntime.rowValue( ...
                pendingRow, "DueSlot", NaN));
            rowDirection = upper(string(sixgr.truth.CoupledTruthRuntime.rowValue( ...
                pendingRow, "Direction", "")));
            rowContextId = string(sixgr.truth.CoupledTruthRuntime.rowValue( ...
                pendingRow, "PUSCHGrantContextId", ""));
            expectedRowBit = logical(sixgr.truth.CoupledTruthRuntime.rowLogical( ...
                pendingRow, "Ack", false));
            if rowDirection ~= "DL" || ~isfinite(rowSourceSlot) || ...
                    rowSourceSlot ~= sourceSlots(bitIdx) || ...
                    ~isfinite(rowHarqId) || rowHarqId ~= harqIds(bitIdx) || ...
                    ~isfinite(currentSlot) || rowDueSlot ~= currentSlot || ...
                    expectedRowBit ~= logical(expectedBits(bitIdx)) || ...
                    (strlength(strtrim(rowContextId)) > 0 && ...
                    strlength(strtrim(puschContextId)) > 0 && rowContextId ~= puschContextId)
                error("sixgr:truth:InvalidPUSCHHARQACKRuntimeBinding", ...
                    "PUSCH HARQ-ACK grant %s failed its exact DL HARQ/source-slot/due-slot/context binding.", ...
                    char(grantIds(bitIdx)));
            end

            rnti = double(sixgr.truth.CoupledTruthRuntime.rowValue( ...
                pendingRow, "RNTI", NaN));
            ueIdx = double(sixgr.truth.CoupledTruthRuntime.rowValue( ...
                pendingRow, "UEIndex", NaN));
            observedAck = logical(observedBits(bitIdx));
            if decodedVectorAvailable
                feedbackOutcome = sixgr.truth.CoupledTruthRuntime. ...
                    ternaryString(observedAck, "ACK", "NACK");
            else
                feedbackOutcome = "DTX";
            end
            harq.onFeedback(rnti, rowHarqId, feedbackOutcome, ...
                "SourceSlot", rowSourceSlot, "FeedbackSlot", currentSlot);
            pid = rowHarqId + 1;
            if observedAck
                try
                    harq.clearSoftBuffer(rnti, rowHarqId);
                catch
                end
                if isfinite(ueIdx) && ueIdx >= 1 && ueIdx <= size(buffers, 1) && ...
                        pid >= 1 && pid <= size(buffers, 2)
                    buffers{round(ueIdx), round(pid)} = [];
                end
            end
            feedbackForScheduler = pendingRow;
            feedbackForScheduler.Ack(1) = observedAck;
            feedbackForScheduler.Processed(1) = true;
            state = sixgr.truth.CoupledTruthRuntime.updateSchedulerAfterFeedback( ...
                state, feedbackForScheduler, "DL");
            pending.Processed(pendingIdx) = true;

            bitMatches = decodedVectorAvailable && ...
                observedAck == logical(expectedBits(bitIdx));
            traceT.ObservedAck(traceIdx) = observedAck;
            traceT.DecodedAck(traceIdx) = observedAck;
            traceT.FalseAck(traceIdx) = decodedVectorAvailable && observedAck && ~expectedRowBit;
            traceT.FalseNack(traceIdx) = decodedVectorAvailable && ~observedAck && expectedRowBit;
            traceT.MissedFeedback(traceIdx) = ~decodedVectorAvailable;
            traceT.PUSCHUCIDecodeOk(traceIdx) = bitMatches;
            traceT.PUCCHDecodeOk(traceIdx) = false;
            traceT.CurrentDecodeOK(traceIdx) = decodedVectorAvailable;
            traceT.CombinedDecodeOK(traceIdx) = bitMatches;
            traceT.BitsCompared(traceIdx) = 1;
            traceT.BitErrors(traceIdx) = double(~bitMatches);
            traceT.UCIContentMatch(traceIdx) = bitMatches;
            traceT.RuntimeStateUpdated(traceIdx) = true;
            traceT.RuntimeStateConsumer(traceIdx) = "HARQEntity.onFeedback_from_PUSCH_UCI";
            traceT.ControlStateChanged(traceIdx) = true;
            traceT.StateChangeApplied(traceIdx) = true;
            traceT.Status(traceIdx) = sixgr.truth.CoupledTruthRuntime. ...
                ternaryString(bitMatches, "PASS", "FAIL");
            if decodedVectorAvailable
                traceT.PUCCHGrantState(traceIdx) = "pusch_uci_feedback_applied";
                traceT.Notes(traceIdx) = "DL HARQ feedback consumed from the same-UE PUSCH receiver UCI output; no standalone PUCCH waveform executed.";
            else
                traceT.PUCCHGrantState(traceIdx) = "pusch_uci_dtx_applied_as_nack";
                traceT.Notes(traceIdx) = "PUSCH receiver produced no usable HARQ-ACK vector; DTX was applied as NACK without substituting expected bits.";
            end

            timeline = sixgr.util.structGet(state, "HARQTimelineTable", table());
            if istable(timeline) && ~isempty(timeline)
                timelineMask = upper(string(timeline.Direction)) == "DL" & ...
                    double(timeline.RNTI) == rnti & ...
                    double(timeline.HarqID) == rowHarqId & ...
                    double(timeline.Slot) == rowSourceSlot;
                if nnz(timelineMask) ~= 1
                    error("sixgr:truth:InvalidPUSCHHARQACKTimelineBinding", ...
                        "PUSCH HARQ-ACK grant %s did not resolve one originating DL HARQ timeline row.", ...
                        char(grantIds(bitIdx)));
                end
                timeline.FeedbackMechanism(timelineMask) = "pusch_uci";
                timeline.FeedbackEvidenceSource(timelineMask) = "same_waveform_pusch_rx_uci";
                state.HARQTimelineTable = timeline;
            end
        end
        state.DLHarq = harq;
        state.DLCombinedLLR = buffers;
        state.PendingFeedbackTable = pending;
        state.PUCCHGrantTraceTable = traceT;
        if istable(sixgr.util.structGet(state, "HARQTimelineTable", table()))
            state.HARQSummaryTable = sixgr.truth.CoupledTruthRuntime. ...
                buildHARQSummary(state.HARQTimelineTable);
        end
    end

    function state = consumeDecodedPUSCHCSI(state, harqOut)
        % Install CSI only from the bit vectors decoded by the current
        % PUSCH receiver. Expected payload bits are used solely to verify
        % the frozen runtime binding; they never replace missing decoded
        % bits and never determine the scheduler value.
        if ~(isstruct(harqOut) && ~isempty(fieldnames(harqOut)))
            return;
        end
        grant = sixgr.util.structGet(harqOut, "GrantSnapshot", ...
            sixgr.util.structGet(harqOut, "Context.GrantSnapshot", struct()));
        reportIdentity = string(sixgr.util.structGet(grant, ...
            "UCIOnPUSCHCSIReportIdentity", ""));
        if ~(isscalar(reportIdentity) && strlength(strtrim(reportIdentity)) > 0)
            return;
        end
        pending = sixgr.util.structGet(state, "PendingCSITable", table());
        if ~(istable(pending) && ~isempty(pending) && ...
                ismember("ReportIdentity", string(pending.Properties.VariableNames)))
            error("sixgr:truth:MissingPUSCHCSIRuntimeRows", ...
                "Decoded PUSCH CSI requires its exact pending CSI report row.");
        end
        transport = lower(strtrim(string( ...
            sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
            pending, "CSIUCITransport", repmat("", height(pending), 1)))));
        mask = string(pending.ReportIdentity) == reportIdentity & ...
            ~logical(pending.Processed) & transport == "pusch_bound";
        if nnz(mask) ~= 1
            error("sixgr:truth:InvalidPUSCHCSIRuntimeBinding", ...
                "PUSCH CSI report %s must bind exactly one unprocessed pending row.", ...
                char(reportIdentity));
        end
        rowIndex = find(mask, 1);
        report = table2struct(pending(rowIndex, :));
        currentSlot = double(sixgr.util.structGet(state, "CurrentSlot", NaN));
        grantContextId = string(sixgr.util.structGet(grant, ...
            "GrantContextId", sixgr.util.structGet(grant, ...
            "PHYGrant.GrantContextId", "")));
        boundContextId = string(report.CSIUCIPUSCHGrantContextId);
        if ~(isfinite(currentSlot) && currentSlot == double(report.DueSlot) && ...
                strlength(strtrim(grantContextId)) > 0 && ...
                grantContextId == boundContextId)
            error("sixgr:truth:InvalidPUSCHCSIRuntimeBinding", ...
                "PUSCH CSI report %s failed its exact due-slot/grant-context binding.", ...
                char(reportIdentity));
        end

        expectedPart1 = int8(sixgr.runtime.RawCSVArrayCodec.decode( ...
            report.CSIPart1BitsToken));
        expectedPart2 = int8(sixgr.runtime.RawCSVArrayCodec.decode( ...
            report.CSIPart2BitsToken));
        receiverExpectedPart1 = int8(sixgr.util.structGet(harqOut, ...
            "ExpectedCSIPart1Bits", int8([])));
        receiverExpectedPart2 = int8(sixgr.util.structGet(harqOut, ...
            "ExpectedCSIPart2Bits", int8([])));
        if ~isequal(expectedPart1(:), receiverExpectedPart1(:)) || ...
                ~isequal(expectedPart2(:), receiverExpectedPart2(:))
            error("sixgr:truth:InconsistentPUSCHCSIBinding", ...
                "PUSCH receiver CSI contract differs from the frozen pending report payload.");
        end
        decodedPart1 = int8(sixgr.util.structGet(harqOut, ...
            "DecodedCSIPart1Bits", int8([])));
        decodedPart2 = int8(sixgr.util.structGet(harqOut, ...
            "DecodedCSIPart2Bits", int8([])));
        decodeOk = numel(decodedPart1) == numel(expectedPart1) && ...
            numel(decodedPart2) == numel(expectedPart2) && ...
            all(ismember(double(decodedPart1(:)), [0 1])) && ...
            all(ismember(double(decodedPart2(:)), [0 1]));
        report.CSIUCIDecodeOk = logical(decodeOk);
        report.CSIUCICRCPass = NaN;
        report.CSIUCIDecodedBitCount = ...
            double(numel(decodedPart1) + numel(decodedPart2));
        report.CSIUCIDecodedBitsToken = char( ...
            sixgr.runtime.RawCSVArrayCodec.encode( ...
            [decodedPart1(:); decodedPart2(:)]));
        if ~decodeOk
            report.Processed = true;
            report.DeliveredSlot = currentSlot;
            report.DeliveryStatus = "pusch_csi_decode_unavailable_not_delivered";
            report.CSIUCITransport = "pusch_decode_failed";
            report.CSIUCIDeliveryReason = ...
                "receiver_did_not_return_complete_binary_csi_parts";
            failedRow = struct2table(report, "AsArray", true);
            state.PendingCSITable(rowIndex, :) = failedRow(:, ...
                state.PendingCSITable.Properties.VariableNames);
            return;
        end

        request = sixgr.util.structGet(state.CfgMobility, ...
            "phy.csi.reportConfiguration", struct());
        request.Rank = max(1, round(double(report.RI)));
        config = sixgr.phy.mimo.CSIReportConfiguration( ...
            request, double(report.CSIConfigurationEpoch));
        decoded = config.decode(decodedPart1, decodedPart2);
        report.CQI = double(sixgr.util.structGet(decoded, ...
            "CQI_CW0", report.CQI));
        report.RI = double(sixgr.util.structGet(decoded, "RI", report.RI));
        report.PMI = double(sixgr.util.structGet(decoded, "PMI", report.PMI));
        report.CRI = double(sixgr.util.structGet(decoded, "CRI", report.CRI));
        report.CSIUCITransport = "pusch_decoded";
        report.CSIUCIDeliveryReason = ...
            "receiver_decoded_typed_csi_ready_for_scheduler";
        decodedRow = struct2table(report, "AsArray", true);
        state.PendingCSITable(rowIndex, :) = decodedRow(:, ...
            state.PendingCSITable.Properties.VariableNames);
        % Re-enter the single causal reducer now that receiver-owned CSI is
        % available. This slot may already have processed PUCCH/HARQ, so
        % only the CSI row remains eligible.
        state.LastDueFeedbackProcessedSlot = NaN;
        state = sixgr.truth.CoupledTruthRuntime.processDueFeedback(state);
    end

    function due = collectPUCCHDueHARQACKImpl(state, dueSlot)
        proto = struct("UEIndex", NaN, "RNTI", NaN, "HarqID", NaN, "SourceSlot", NaN, ...
            "PUCCHGrantId", "", "AckBit", int8(0), "EvidenceSource", "");
        due = repmat(proto, 0, 1);
        dueSlot = round(double(dueSlot));
        if ~(isfinite(dueSlot) && dueSlot >= 1)
            return;
        end
        pendingFeedback = sixgr.util.structGet(state, "PendingFeedbackTable", table());
        if istable(pendingFeedback) && ~isempty(pendingFeedback)
            for ri = 1:height(pendingFeedback)
                row = pendingFeedback(ri, :);
                rowDueSlot = double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "DueSlot", ...
                    sixgr.truth.CoupledTruthRuntime.rowValue(row, "ScheduledAbsoluteSlot", NaN)));
                if ~(isfinite(rowDueSlot) && abs(rowDueSlot - dueSlot) < 1e-9)
                    continue;
                end
                if logical(sixgr.truth.CoupledTruthRuntime.rowLogical(row, "Processed", false)) || ...
                        logical(sixgr.truth.CoupledTruthRuntime.rowLogical(row, "RightCensored", false))
                    continue;
                end
                deliveryMechanism = lower(strtrim(string( ...
                    sixgr.truth.CoupledTruthRuntime.rowValue(row, "DeliveryMechanism", "pucch"))));
                if deliveryMechanism == "pusch_uci"
                    continue;
                end
                due(end + 1, 1) = sixgr.truth.CoupledTruthRuntime.buildDueHARQACKStruct(row, "pending_feedback_table"); %#ok<AGROW>
            end
        end
        pucchGrants = sixgr.util.structGet(state, "PUCCHGrantTraceTable", table());
        if istable(pucchGrants) && ~isempty(pucchGrants)
            for ri = 1:height(pucchGrants)
                row = pucchGrants(ri, :);
                rowDueSlot = double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "ScheduledAbsoluteSlot", ...
                    sixgr.truth.CoupledTruthRuntime.rowValue(row, "Slot", NaN)));
                if ~(isfinite(rowDueSlot) && abs(rowDueSlot - dueSlot) < 1e-9)
                    continue;
                end
                if logical(sixgr.truth.CoupledTruthRuntime.rowLogical(row, "GrantExecutedFlag", false)) || ...
                        logical(sixgr.truth.CoupledTruthRuntime.rowLogical(row, "CanceledAtSweepBoundary", false)) || ...
                        logical(sixgr.truth.CoupledTruthRuntime.rowLogical(row, "RightCensored", false))
                    continue;
                end
                if logical(sixgr.truth.CoupledTruthRuntime.rowLogical(row, "MultiplexedOnPUSCH", false))
                    continue;
                end
                due(end + 1, 1) = sixgr.truth.CoupledTruthRuntime.buildDueHARQACKStruct(row, "pucch_grant_trace"); %#ok<AGROW>
            end
        end
        if numel(due) > 1
            ids = string({due.PUCCHGrantId}).';
            [~, keep] = unique(ids, "stable");
            due = due(sort(keep));
        end
    end

    function due = buildDueHARQACKStruct(row, source)
        due = struct("UEIndex", double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "UEIndex", NaN)), ...
            "RNTI", double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "RNTI", NaN)), ...
            "HarqID", double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "HarqID", NaN)), ...
            "SourceSlot", double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "SourceSlot", NaN)), ...
            "PUCCHGrantId", char(string(sixgr.truth.CoupledTruthRuntime.rowValue(row, "PUCCHGrantId", ""))), ...
            "AckBit", int8(logical(sixgr.truth.CoupledTruthRuntime.rowValue(row, "Ack", ...
                sixgr.truth.CoupledTruthRuntime.rowValue(row, "ExpectedAck", false)))), ...
            "EvidenceSource", char(string(source)));
    end

    function [grantsOut, blockedT] = excludeULGrantsCollidingWithPUCCHImpl(state, grantsIn, dueSlot)
        grantsOut = grantsIn;
        blockedPrototype = sixgr.truth.CoupledTruthRuntime.emptyPUSCHPUCCHCollisionRow();
        blockedT = struct2table(repmat(blockedPrototype, 0, 1));
        if ~(isstruct(grantsIn) && ~isempty(grantsIn))
            return;
        end
        [dueUEs, dueRNTIs, dueSourceSlots, dueGrantIds, dueEvidenceSources] = ...
            sixgr.truth.CoupledTruthRuntime.collectPUCCHDueIdentityImpl(state, dueSlot);
        if isempty(dueUEs) && isempty(dueRNTIs)
            return;
        end
        dueSlot = round(double(dueSlot));

        keep = true(1, numel(grantsIn));
        blockedRows = repmat(blockedPrototype, max(1, numel(grantsIn)), 1);
        blockedCount = 0;
        for gi = 1:numel(grantsIn)
            grant = grantsIn(gi);
            ueIdx = double(sixgr.util.structGet(grant, "UEIndex", NaN));
            rnti = double(sixgr.util.structGet(grant, "RNTI", NaN));
            if ~(isfinite(ueIdx) && ueIdx >= 1) && isfinite(rnti)
                ueIdx = sixgr.truth.CoupledTruthRuntime.resolveUEIndexFromRNTI(state, rnti);
            end
            match = false(size(dueUEs));
            if isfinite(ueIdx)
                match = match | (isfinite(dueUEs) & abs(dueUEs - ueIdx) < 1e-9);
            end
            if isfinite(rnti)
                match = match | (isfinite(dueRNTIs) & abs(dueRNTIs - rnti) < 1e-9);
            end
            matchIdx = find(match, 1, "first");
            if isempty(matchIdx)
                continue;
            end
            % Any identity returned by collectPUCCHDueIdentityImpl is still
            % eligible for standalone PUCCH.  A valid UCI-on-PUSCH transfer
            % atomically marks both the pending row and control trace, so it
            % is excluded before reaching this branch.  Never accept a bare
            % ExpectedUCIBits vector as proof of transfer: stale snapshots
            % and partially populated grants can carry bits without owning
            % the exact pending PUCCH identities or typed UCI payload.
            keep(gi) = false;
            blockedCount = blockedCount + 1;
            blockedRows(blockedCount).Direction = "UL";
            blockedRows(blockedCount).DueSlot = double(dueSlot);
            blockedRows(blockedCount).UEIndex = double(ueIdx);
            blockedRows(blockedCount).RNTI = double(rnti);
            blockedRows(blockedCount).PUSCHGrantSlot = double(sixgr.util.structGet(grant, "ScheduledAbsoluteSlot", ...
                sixgr.util.structGet(grant, "Slot", NaN)));
            blockedRows(blockedCount).PUCCHSourceSlot = double(dueSourceSlots(matchIdx));
            blockedRows(blockedCount).PUCCHGrantId = char(dueGrantIds(matchIdx));
            blockedRows(blockedCount).CollisionEvidenceSource = char(dueEvidenceSources(matchIdx));
            blockedRows(blockedCount).Reason = "harq_ack_pucch_due_same_slot_same_ue";
            blockedRows(blockedCount).Policy = "avoid_standalone_pusch_without_uci_on_pusch_multiplexing";
        end

        grantsOut = grantsIn(keep);
        if blockedCount > 0
            blockedT = struct2table(blockedRows(1:blockedCount), "AsArray", true);
        end
    end

    function row = emptyPUSCHPUCCHCollisionRow()
        row = struct( ...
            "Direction", "", "DueSlot", NaN, "UEIndex", NaN, "RNTI", NaN, ...
            "PUSCHGrantSlot", NaN, "PUCCHSourceSlot", NaN, "PUCCHGrantId", "", ...
            "CollisionEvidenceSource", "", "Reason", "", "Policy", "");
    end

    function row = emptyPacketDeliveryLedgerRow()
        row = struct( ...
            "Direction", "", "UEIndex", NaN, "RNTI", NaN, ...
            "PacketId", "", "ApplicationPacketId", "", "FlowId", "", "QFI", NaN, ...
            "EnqueueFrame", NaN, "EnqueueSlot", NaN, "EnqueueCanonicalSlot", NaN, "EnqueueSlotInFrame", NaN, "EnqueueTime_s", NaN, ...
            "OfferedBits", NaN, "ScheduledBits", 0, "DeliveredBits", 0, "RemainingBits", 0, ...
