    function cqi = schedulerResolvedCQI(row)
        cqi = double(sixgr.truth.CoupledTruthRuntime.rowValue( ...
            row, "SchedulerResolvedCQI", NaN));
        if isfinite(cqi) && cqi > 0
            return;
        end
        status = lower(strtrim(string(sixgr.truth.CoupledTruthRuntime.rowValue( ...
            row, "MCSValueStatus", ""))));
        if contains(status, "unavailable") || contains(status, "rejected") || ...
                contains(status, "failed")
            cqi = NaN;
            return;
        end
        rawCQI = double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "CQI", NaN));
        if isfinite(rawCQI) && rawCQI > 0
            cqi = rawCQI;
        else
            cqi = NaN;
        end
    end

    function dueSlot = nextLegalULControlSlot(cfg, requestedSlot)
        dueSlot = max(0, round(double(requestedSlot)));
        [controlStart, controlCount] = ...
            sixgr.truth.CoupledTruthRuntime.configuredCSIControlSymbols(cfg);
        slotsPerFrame = max(1, round(double(sixgr.util.structGet( ...
            cfg, "frame.slotsPerFrame", 10))));
        searchLimit = max(20, 4 * slotsPerFrame);
        for offset = 0:searchLimit
            candidate = dueSlot + offset;
            [~, allowUL, ~, partition] = ...
                sixgr.truth.CoupledTruthRuntime.slotDuplexState(cfg, candidate);
            ulSymbols = double(sixgr.util.structGet( ...
                partition, "ULSymbolAllocation", [0 0]));
            ulStart = NaN;
            ulCount = NaN;
            if numel(ulSymbols) >= 2
                ulStart = ulSymbols(1);
                ulCount = ulSymbols(2);
            end
            controlFits = isfinite(ulStart) && isfinite(ulCount) && ...
                controlStart >= ulStart && ...
                controlStart + controlCount <= ulStart + ulCount;
            if logical(allowUL) && controlFits
                dueSlot = candidate;
                return;
            end
        end
        error("sixgr:truth:NoLegalCSIUplinkOccasion", ...
            ["No legal UL control occasion exists within %d slots after " + ...
             "the configured CSI feedback due slot %d."], ...
            searchLimit, round(double(requestedSlot)));
    end

    function [symbolStart, symbolCount] = configuredCSIControlSymbols(cfg)
        section = sixgr.util.structGet(cfg, ...
            "validation.pucch_resources", struct());
        ids = double(sixgr.util.structGet(section, ...
            "csi_resource_ids", []));
        resources = sixgr.util.structGet(section, "resources", struct([]));
        if isempty(ids) || ~isstruct(resources) || isempty(resources)
            error("sixgr:truth:MissingCSIControlResource", ...
                "CSI reporting requires an explicit YAML PUCCH CSI resource.");
        end
        resourceId = ids(1);
        hit = [];
        for index = 1:numel(resources)
            candidateId = double(sixgr.util.structGet(resources(index), ...
                "id", sixgr.util.structGet(resources(index), "resource_id", NaN)));
            if isequal(candidateId, resourceId)
                hit = resources(index);
                break;
            end
        end
        if isempty(hit)
            error("sixgr:truth:MissingCSIControlResource", ...
                "Configured CSI PUCCH resource %g is absent.", resourceId);
        end
        symbolStart = double(sixgr.util.structGet(hit, "starting_symbol", ...
            sixgr.util.structGet(hit, "symbol_start", NaN)));
        symbolCount = double(sixgr.util.structGet(hit, "nrof_symbols", ...
            sixgr.util.structGet(hit, "num_symbols", NaN)));
        if ~(isfinite(symbolStart) && isfinite(symbolCount) && ...
                symbolStart >= 0 && symbolCount >= 1)
            error("sixgr:truth:MissingCSIControlResource", ...
                "Configured CSI PUCCH resource has invalid symbol coordinates.");
        end
    end

    function report = attachTypedCSIUCIPayload(report, cfg)
        request = sixgr.util.structGet(cfg, ...
            "phy.csi.reportConfiguration", struct());
        epoch = double(sixgr.util.structGet(cfg, ...
            "phy.csi.reportConfigurationEpoch", ...
            sixgr.util.structGet(request, "Epoch", NaN)));
        if ~(isstruct(request) && ~isempty(fieldnames(request)) && ...
                strlength(strtrim(string(sixgr.util.structGet( ...
                request, "ReportConfigID", "")))) > 0 && isfinite(epoch))
            error("sixgr:truth:MissingRuntimeCSIReportConfiguration", ...
                ["DL CSI reporting is enabled but the active YAML did not " + ...
                 "resolve a typed CSI report configuration."]);
        end
        measuredRank = max(1, round(double(report.RI)));
        maxRank = max(1, round(double(sixgr.util.structGet( ...
            request, "MaxRank", measuredRank))));
        request.Rank = min(measuredRank, maxRank);
        reportConfig = sixgr.phy.mimo.CSIReportConfiguration(request, epoch);
        values = struct( ...
            "CRI", max(0, round(double(report.CRI))), ...
            "RI", request.Rank, ...
            "CQI_CW0", max(0, min(15, round(double(report.CQI)))), ...
            "PMI", max(0, round(double(report.PMI))), ...
            "LI", max(0, request.Rank - 1));
        encoded = reportConfig.build(values);
        report.CSIReportConfigID = char(reportConfig.ReportConfigID);
        report.CSIConfigurationEpoch = double(reportConfig.Epoch);
        report.CSIUCIChannel = char(reportConfig.UCIChannel);
        report.CSIPart1BitsToken = char( ...
            sixgr.runtime.RawCSVArrayCodec.encode(int8(encoded.Part1Bits(:))));
        report.CSIPart2BitsToken = char( ...
            sixgr.runtime.RawCSVArrayCodec.encode(int8(encoded.Part2Bits(:))));
        report.CSIPart1BitCount = double(numel(encoded.Part1Bits));
        report.CSIPart2BitCount = double(numel(encoded.Part2Bits));
        report.CSIUCIBitCount = report.CSIPart1BitCount + ...
            report.CSIPart2BitCount;
        report.CSIUCITransport = lower(char(reportConfig.UCIChannel));
        report.CSIUCIDeliveryReason = ...
            "typed_csi_report_waiting_for_receiver_decode";
    end

    function [state, report, delivered] = executeDueDLCSIReport(state, report)
        delivered = false;
        ueIdx = max(1, round(double(report.UEIndex)));
        cfgU = state.CfgMobility;
        [cfgU, state] = sixgr.truth.CoupledTruthRuntime. ...
            applyUserContextImpl(cfgU, state, ueIdx, "UL");
        cfgU = sixgr.util.structSet(cfgU, "phy.rnti", double(report.RNTI));
        part1 = int8(sixgr.runtime.RawCSVArrayCodec.decode( ...
            report.CSIPart1BitsToken));
        part2 = int8(sixgr.runtime.RawCSVArrayCodec.decode( ...
            report.CSIPart2BitsToken));
        request = sixgr.util.structGet(cfgU, ...
            "phy.csi.reportConfiguration", struct());
        epoch = double(report.CSIConfigurationEpoch);
        request.Rank = max(1, round(double(report.RI)));
        reportConfig = sixgr.phy.mimo.CSIReportConfiguration(request, epoch);
        reportConfig.validateDecoded(part1, part2);

        dueSlot = double(state.CurrentSlot);
        sourceSlot = double(report.SourceSlot);
        [~, ~, ~, partition] = ...
            sixgr.truth.CoupledTruthRuntime.slotDuplexState(cfgU, dueSlot);
        symbolsPerSlot = double(sixgr.util.structGet(state, ...
            "SymbolsPerSlot", []));
        if ~(isscalar(symbolsPerSlot) && isfinite(symbolsPerSlot) && ...
                symbolsPerSlot > 0 && symbolsPerSlot == round(symbolsPerSlot))
            error("sixgr:truth:MissingRuntimeSymbolsPerSlot", ...
                ["CSI UCI delivery requires the symbol count resolved by " ...
                 "the canonical frame runtime; no local slot-size fallback is permitted."]);
        end
        ownership = repmat('F', 1, symbolsPerSlot);
        ownership = localApplyOwnership(ownership, ...
            sixgr.util.structGet(partition, "DLSymbolAllocation", [0 0]), 'D');
        ownership = localApplyOwnership(ownership, ...
            sixgr.util.structGet(partition, "GuardSymbolAllocation", [0 0]), 'G');
        ownership = localApplyOwnership(ownership, ...
            sixgr.util.structGet(partition, "ULSymbolAllocation", ...
            [0 symbolsPerSlot]), 'U');
        [componentCarrier, activeULBWP] = ...
            sixgr.truth.CoupledTruthRuntime.resolvePUCCHCarrierBWP( ...
            cfgU, struct2table(report, "AsArray", true));
        ueState = struct("UEID", ueIdx, "RNTI", double(report.RNTI), ...
            "ServingCell", double(report.ServingCell), ...
            "PUCCHCell", double(report.ServingCell), ...
            "ComponentCarrier", componentCarrier, ...
            "ActiveULBWP", activeULBWP);
        priAuthority = sixgr.phy.pucch.resolveConfiguredPRI(cfgU, ...
            ueIdx, double(report.RNTI), NaN, "csi");
        frameState = struct( ...
            "K1", dueSlot - sourceSlot, ...
            "K1Source", "configured_csi_report_delay_and_duplex_resolution", ...
            "PDSCHEndSlot", sourceSlot, "TargetSlot", dueSlot, ...
            "DecodedPRI", priAuthority.PRIValue, "PRIFieldWidth", 3, ...
            "PRIProvenance", priAuthority.Source, ...
            "FirstCCE", 0, "NumCCE", 24, ...
            "SlotSymbolOwnership", string(ownership), ...
            "FlexibleResolutionProvided", false, ...
            "TriggeringEventID", string(report.ReportIdentity));
        connected = sixgr.phy.pucch.PUCCHConfigBuilder.connectedCSI( ...
            cfgU, ueState, part1, part2, frameState);

        resource = connected.Assignment.Resource.Data;
        pucchGrantId = char("PUCCH-CSI-" + string(report.ReportIdentity));
        feedback = struct( ...
            "Direction", "DL", "FeedbackForDirection", "DL", ...
            "UEIndex", ueIdx, "RNTI", double(report.RNTI), ...
            "ServingCell", double(report.ServingCell), ...
            "BaseStationID", double(report.ServingCell), ...
            "ComponentCarrier", componentCarrier, ...
            "ActiveULBWP", activeULBWP, ...
            "SourceSlot", sourceSlot, "DueSlot", dueSlot, ...
            "ScheduledAbsoluteSlot", dueSlot, "HarqID", NaN, ...
            "TBSBits", NaN, "Ack", false, ...
            "UCIBitCount", double(numel(part1) + numel(part2)), ...
            "UCIType", "csi_part1_part2", ...
            "PRIValue", priAuthority.PRIValue, ...
            "PRIProvenance", priAuthority.Source, ...
            "PUCCHGrantId", pucchGrantId, ...
            "RequestedFormat", double(connected.Assignment.Format), ...
            "ResolvedFormat", double(connected.Assignment.Format), ...
            "FormatAdaptationReason", "none_strict_assignment", ...
            "PUCCHResourceId", char(string(resource.ID)), ...
            "PUCCHPRBStart", double(resource.StartPRB), ...
            "PUCCHPRBCount", double(resource.NumPRBs), ...
            "PUCCHSymbolStart", double(resource.StartSymbol), ...
            "PUCCHNumSymbols", double(resource.NumSymbols), ...
            "ControlResourceSource", ...
            "typed_yaml_csi_pucch_resource_assignment", ...
            "ControlResourceValidity", true);
        feedbackT = struct2table(feedback, "AsArray", true);
        state = sixgr.truth.CoupledTruthRuntime. ...
            appendPUCCHGrantTraceFromFeedback(state, feedbackT);

        pucchSNR_dB = sixgr.truth.resolvePUCCHConfiguredSNRMetadata( ...
            state, cfgU);
        carrier = sixgr.phy.grid.makeCarrier(cfgU);
        channelProfile = sixgr.channel.resolveConcreteProfile(cfgU);
        [state, interferenceBundle] = ...
            sixgr.truth.CoupledTruthRuntime.buildPUCCHInterferenceBundle( ...
            state, feedbackT);
        [state, channelState] = ...
            sixgr.truth.CoupledTruthRuntime.acquireRuntimeChannelStateForControl( ...
            state, cfgU, ueIdx, "UL");
        trial = sixgr.link.runPUCCHWaveformTrial(cfgU, ...
            "Carrier", carrier, "Assignment", connected.Assignment, ...
            "Report", connected.Report, ...
            "ReceiverContext", connected.ReceiverContext, ...
            "SNR_dB", double(pucchSNR_dB), ...
            "ChannelProfile", channelProfile, ...
            "Seed", max(1, round(dueSlot)), ...
            "InitialRuntimeChannelState", channelState, ...
            "InterferenceBundle", interferenceBundle);
        state = sixgr.truth.CoupledTruthRuntime.commitRuntimeChannelState( ...
            state, sixgr.util.structGet(trial, ...
            "UpdatedRuntimeChannelState", struct()));
        executedTx = sixgr.util.structGet(trial, "Transmitter", struct());
        if isstruct(executedTx) && isfield(executedTx, "PUCCHIndices")
            observedRE = sixgr.truth.buildObservedREAllocation(executedTx, ...
                "Direction", "UL", "Channel", "PUCCH", ...
                "AbsoluteSlot", max(0, round(dueSlot) - 1), ...
                "CellID", double(report.ServingCell), "UEID", ueIdx, ...
                "AllocationID", "pucch_csi_slot_" + ...
                string(max(0, round(dueSlot) - 1)) + "_ue_" + string(ueIdx));
            state.ObservedREAllocationTable = ...
                sixgr.truth.CoupledTruthRuntime.appendObservedREAllocation( ...
                state.ObservedREAllocationTable, observedRE);
        end
        decodedBits = int8(sixgr.util.structGet(trial, ...
            "DecodedBits", int8([])));
        serializedReport = sixgr.phy.pucch.UCIReportSerializer.serialize( ...
            connected.Report);
        decodedReport = struct("InformationBits", int8([]), ...
            "CSIPart1Bits", int8([]), "CSIPart2Bits", int8([]), ...
            "PaddingBits", int8([]));
        wireLayoutOk = false;
        try
            decodedReport = sixgr.phy.pucch.UCIReportSerializer. ...
                extractDecodedInformationBits(serializedReport, decodedBits);
            wireLayoutOk = true;
        catch ME
            if ~strcmp(ME.identifier, "sixgr:phy:pucch:UCILengthMismatch")
                rethrow(ME);
            end
        end
        decodeOk = logical(sixgr.util.structGet(trial, ...
            "ReceiverUsable", false)) && ...
            ~logical(sixgr.util.structGet(trial, "DTXFlag", true)) && ...
            logical(sixgr.util.structGet(trial, "UCIContentMatch", false)) && ...
            wireLayoutOk && ...
            numel(decodedReport.CSIPart1Bits) == numel(part1) && ...
            numel(decodedReport.CSIPart2Bits) == numel(part2);
        crcApplicable = logical(sixgr.util.structGet(trial, ...
            "CRCApplicable", false));
        crcPass = double(sixgr.util.structGet(trial, "CRCPass", NaN));
        if crcApplicable
            decodeOk = decodeOk && isfinite(crcPass) && logical(crcPass);
        end
        observed = struct( ...
            "ExpectedAck", false, "ObservedAck", false, ...
            "DecodedAck", false, "DecodeOk", decodeOk, ...
            "DTXFlag", logical(sixgr.util.structGet(trial, "DTXFlag", true)), ...
            "MissedFeedback", ~decodeOk, "FalseAck", false, ...
            "FalseNack", false, "ExpectedBits", [part1; part2], ...
            "DecodedBits", decodedBits, ...
            "PhysicalOccasionId", char(connected.Assignment.AssignmentID), ...
            "LogicalPUCCHGrantIdSet", pucchGrantId);
        state = sixgr.truth.CoupledTruthRuntime.appendPUCCHFeedbackTrial( ...
            state, feedbackT, trial, observed);
        state = sixgr.truth.CoupledTruthRuntime. ...
            updatePUCCHGrantTraceAfterObservation(state, feedbackT, observed);

        report.CSIUCIDecodeOk = logical(decodeOk);
        report.CSIUCICRCPass = crcPass;
        report.CSIUCIDecodedBitCount = double(numel(decodedReport.InformationBits));
        report.CSIUCIDecodedBitsToken = char( ...
            sixgr.runtime.RawCSVArrayCodec.encode(decodedReport.InformationBits));
        if ~decodeOk
            report.CSIUCIDeliveryReason = ...
                "receiver_decode_or_content_validation_failed";
            return;
        end
        p1Decoded = decodedReport.CSIPart1Bits;
        p2Decoded = decodedReport.CSIPart2Bits;
        decoded = reportConfig.decode(p1Decoded, p2Decoded);
        report.CQI = double(sixgr.util.structGet(decoded, ...
            "CQI_CW0", report.CQI));
        report.RI = double(sixgr.util.structGet(decoded, "RI", report.RI));
        report.PMI = double(sixgr.util.structGet(decoded, "PMI", report.PMI));
        report.CRI = double(sixgr.util.structGet(decoded, "CRI", report.CRI));
        report.CSIUCIDeliveryReason = ...
            "receiver_decoded_typed_csi_delivered_to_scheduler";
        delivered = true;
    end

    function report = applyCombinedPUCCHCSIObservation(state, report, observed)
        % Consume CSI only from the owner-labelled bits decoded from the
        % same physical PUCCH waveform as HARQ-ACK.  No configured CQI/PMI
        % value is substituted when the receiver cannot recover the typed
        % UCI layout.
        p1Decoded = int8(sixgr.util.structGet(observed, ...
            "DecodedCSIPart1Bits", int8([])));
        p2Decoded = int8(sixgr.util.structGet(observed, ...
            "DecodedCSIPart2Bits", int8([])));
        informationBits = int8(sixgr.util.structGet(observed, ...
            "DecodedCSIInformationBits", [p1Decoded; p2Decoded]));
        decodeOk = logical(sixgr.util.structGet(observed, ...
            "CSIDecodeOk", false));
        report.CSIUCITransport = "pucch_decoded";
        report.CSIUCIDecodeOk = decodeOk;
        report.CSIUCICRCPass = double(sixgr.util.structGet( ...
            observed, "CSICRCPass", NaN));
        report.CSIUCIDecodedBitCount = double(numel(informationBits));
        report.CSIUCIDecodedBitsToken = char( ...
            sixgr.runtime.RawCSVArrayCodec.encode(informationBits));
        if ~decodeOk
            report.CSIUCIDeliveryReason = ...
                "combined_pucch_receiver_decode_or_content_validation_failed";
            return;
        end

        request = sixgr.util.structGet(state.CfgMobility, ...
            "phy.csi.reportConfiguration", struct());
        request.Rank = max(1, round(double(report.RI)));
        reportConfig = sixgr.phy.mimo.CSIReportConfiguration( ...
            request, double(report.CSIConfigurationEpoch));
        reportConfig.validateDecoded(p1Decoded, p2Decoded);
        decoded = reportConfig.decode(p1Decoded, p2Decoded);
        report.CQI = double(sixgr.util.structGet(decoded, ...
            "CQI_CW0", report.CQI));
        report.RI = double(sixgr.util.structGet(decoded, "RI", report.RI));
        report.PMI = double(sixgr.util.structGet(decoded, "PMI", report.PMI));
        report.CRI = double(sixgr.util.structGet(decoded, "CRI", report.CRI));
        report.CSIUCIDeliveryReason = ...
            "combined_pucch_receiver_decoded_typed_csi_delivered_to_scheduler";
    end

