            "MUMIMOAdmissionReceiveCombiningMatrixSHA256", "", ...
            "MUMIMOReceiveProcessingMode", "", "MUMIMOReceiverAlgorithm", "", ...
            "MUMIMOHybridRFDesignPolicy", "", "MUMIMOHybridRFDesignStatus", "", ...
            "HybridElementToPortMatrixSHA256", "", "BaseHybridElementToPortMatrixSHA256", "", ...
            "NumLogicalPorts", NaN, "NumRFChains", NaN, ...
            "ConfiguredBeamSelectionStrategy", "", "PrecoderSource", "", "PrecodingMode", "", "PrecodingApplicationStage", "", ...
            "PrecodingActive", false, "ExplicitBeamWeightsApplied", false, "TransformPrecodingApplied", false, "BeamformingApplied", false, ...
            "AppliedBeamIndexSet", "", "AppliedPrecoderPMI", NaN, "AppliedPrecoderPMIType", "", "AppliedPrecoderCodebookMode", "", ...
            "AppliedPrecoderMatrixSHA256", "", "RequestedPrecoderSHA256", "", "AppliedPrecoderSHA256", "", "PrecoderDigestDomain", "", "FrozenGrantContextId", "", ...
            "PrecodingNumPorts", NaN, "PrecodingNumLayers", NaN, "PrecodingMatrixRows", NaN, "PrecodingMatrixCols", NaN, ...
            "GrantContextId", "", "GrantWorkerSafe", false, "GrantSharedStateCommitMode", "", ...
            "QueueBytesBefore", NaN, "QueueBytesAfter", NaN, ...
            "PBCHGatingActive", false, "PRACHGatingActive", false, "PDCCHGatingActive", false, "SRSGatingActive", false, ...
            "ControlEligible", false, "SchedulingEligible", false, "SchedulingBlockedBySRS", false, ...
            "ControlDecodeOk", false, "PDCCHCausalGrantDecodeOk", false, ...
            "PDCCHControlFailureReason", "", "PDCCHControlEvidenceSource", "", ...
            "ControlDecodeSource", "", "GrantControlState", "", ...
            "CellAcquisitionState", "", "AccessState", "", "SRSValidityState", "", "CSIValidityState", "", ...
            "SRSValid", false, "LastSuccessfulSRSSlot", NaN, "SRSAgeSlots", NaN, ...
            "TRSGatingActive", false, "TRSValidityState", "", "TrackingEligibility", false, "TRSAgeSlots", NaN, ...
            "LastSuccessfulTRSSlot", NaN, "LastEstimatedTRSDopplerHz", NaN, ...
            "TRSStateSource", "", "TRSRuntimeConsumer", "", "TRSInfluencedDecision", false, ...
            "TRSInfluenceDefinition", "", "TRSReceiverIntegrationStatus", "", "TRSReceiverIntegrationBlocker", "");
    end

    function row = emptyControlSummaryRow()
        row = struct( ...
            "ControlIntegrationMode", "", "CurrentSchedulingDirection", "", ...
            "PBCHGatingActive", false, "PRACHGatingActive", false, "PDCCHGatingActive", false, "SRSGatingActive", false, ...
            "TRSGatingActive", false, ...
            "PBCHFailureCount", 0, "PRACHFailureCount", 0, "ControlDecodeFailureCount", 0, ...
            "PUCCHDecodeFailureCount", 0, "PUCCHCrashCount", 0, ...
            "TRSFailureCount", 0, ...
            "SRSInvalidEventCount", 0, "SchedulingOpportunitiesBlockedByGating", 0, "GrantsBlockedByGating", 0, ...
            "UsersAcquired", 0, "UsersAccessReady", 0, "UsersWithValidSRS", 0, "UsersWithValidTRS", 0, ...
            "UsersControlEligible", 0, "UsersDLSchedulingEligible", 0, "UsersULSchedulingEligible", 0, ...
            "UsersSchedulingEligible", 0, "UsersSchedulingBlockedBySRS", 0, ...
            "DLGrantsScheduledWithInvalidSRS", 0, "ULGrantsScheduledWithInvalidSRS", 0);
    end

    function row = emptyControlStateRow()
        row = struct( ...
            "UEIndex", NaN, "RNTI", NaN, "ServingCell", NaN, "CurrentSchedulingDirection", "", ...
            "CellAcquisitionState", "", "AccessState", "", "LastPDCCHStatus", "", ...
            "TimeAlignmentState", "", "LastTimingAdvance_samples", NaN, "LastTimingAdvance_us", NaN, ...
            "LastTimingAdvanceSource", "", "LastTimingAdvanceUpdateSlot", NaN, ...
            "LastTimingAdvanceServingCell", NaN, "LastTimingAdvanceServingDistance_m", NaN, ...
            "TimingAdvanceDrift_samples", NaN, "TimingAdvanceDrift_us", NaN, ...
            "TimingAdvanceUpdateRequired", false, "TimingAdvanceUpdateStatus", "", ...
            "SRSValidityState", "", "CSIValidityState", "", "TRSValidityState", "", ...
            "SharedSchedulingEligibility", false, "DLSchedulingEligibility", false, "ULSchedulingEligibility", false, ...
            "SchedulingEligibility", false, "ControlEligibility", false, "SchedulingBlockedBySRS", false, ...
            "CoverageEligibility", true, "CoverageOutageState", "", ...
            "SRSValid", false, "SRSAgeSlots", NaN, "TrackingEligibility", false, "TRSAgeSlots", NaN, ...
            "LastSuccessfulPBCHSlot", NaN, "LastSuccessfulPRACHSlot", NaN, ...
            "LastSuccessfulPDCCHSlot", NaN, "LastSuccessfulPUCCHSlot", NaN, "LastSuccessfulSRSSlot", NaN, ...
            "LastSuccessfulTRSSlot", NaN, "LastEstimatedTRSDopplerHz", NaN, ...
            "TRSRuntimeConsumer", "", "TRSReceiverIntegrationStatus", "", "TRSReceiverIntegrationBlocker", "", ...
            "TRSProcessed", false, "TRSUpdateOutcome", "", "TRSTrackingStateAfter", "", "TRSRuntimeEvidenceSource", "", ...
            "PBCHFailureCount", 0, "PRACHFailureCount", 0, ...
            "ControlDecodeFailureCount", 0, "PUCCHDecodeFailureCount", 0, "PUCCHCrashCount", 0, "SRSInvalidEventCount", 0, "TRSFailureCount", 0, ...
            "SchedulingOpportunitiesBlockedByGating", 0, "GrantsBlockedByGating", 0, "DLGrantsScheduledWithInvalidSRS", 0, "ULGrantsScheduledWithInvalidSRS", 0);
    end

    function [state, observed] = observePUCCHFeedback(state, feedbackRow, csiReport)
        if nargin < 3 || ~isstruct(csiReport)
            csiReport = struct();
        end
        observed = struct("ExpectedAck", false, "ObservedAck", false, "DecodedAck", false, ...
            "DecodeOk", false, "DTXFlag", false, "MissedFeedback", true, ...
            "FalseAck", false, "FalseNack", false, ...
            "ExpectedBits", int8([]), "DecodedBits", int8([]), ...
            "PhysicalOccasionId", "", "LogicalPUCCHGrantIdSet", "", ...
            "LogicalFeedbackCount", 0, "CSIReportIdentity", "", ...
            "CSIDecodeOk", false, "DecodedCSIPart1Bits", int8([]), ...
            "DecodedCSIPart2Bits", int8([]), ...
            "DecodedCSIInformationBits", int8([]), "CSIWireLayoutOk", false, ...
            "CSICRCPass", NaN);
        if ~(istable(feedbackRow) && height(feedbackRow) >= 1)
            return;
        end
        feedbackRow = sixgr.truth.CoupledTruthRuntime. ...
            validateAndOrderPUCCHPhysicalOccasion(feedbackRow);
        row = feedbackRow(end, :);
        ueIdx = max(1, round(double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "UEIndex", NaN))));
        if ~(isfinite(ueIdx) && ueIdx >= 1 && ueIdx <= double(sixgr.util.structGet(state, "NumUsers", 0)))
            return;
        end
        cfgU = state.CfgMobility;
        [cfgU, state] = sixgr.truth.CoupledTruthRuntime.applyUserContextImpl(cfgU, state, ueIdx, "UL");
        cfgU = sixgr.util.structSet(cfgU, "phy.rnti", double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "RNTI", NaN)));
        sixgr.config.assertRuntimeFeatureUse(cfgU, "pucch", ...
            logical(sixgr.util.structGet(cfgU, "phy.pucch.enable", false)), ...
            "CoupledTruthRuntime.observePUCCHFeedback");
        if height(feedbackRow) == 1
            prbStart = double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "PUCCHPRBStart", NaN));
            prbCount = max(1, round(double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "PUCCHPRBCount", 1))));
            if isfinite(prbStart)
                cfgU = sixgr.util.structSet(cfgU, "phy.pucch.PRBSet", double(prbStart) + (0:max(prbCount - 1, 0)));
            end
            symStart = double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "PUCCHSymbolStart", NaN));
            numSym = max(1, round(double(sixgr.truth.CoupledTruthRuntime.rowValue(row, "PUCCHNumSymbols", 1))));
            if isfinite(symStart)
                cfgU = sixgr.util.structSet(cfgU, "phy.pucch.SymbolAllocation", [double(symStart) numSym]);
            end
        end
        expectedBits = int8(false(height(feedbackRow), 1));
        for bitIndex = 1:height(feedbackRow)
            expectedBits(bitIndex) = int8(sixgr.truth.CoupledTruthRuntime. ...
                rowExpectedPUCCHAck(feedbackRow(bitIndex, :)));
        end
        expectedAck = logical(expectedBits(1));
        observed.ExpectedAck = expectedAck;
        observed.ExpectedBits = expectedBits;
        grantIds = string(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
            feedbackRow, "PUCCHGrantId", repmat("", height(feedbackRow), 1)));
        if any(strlength(strtrim(grantIds)) == 0) || numel(unique(grantIds)) ~= numel(grantIds)
            error("sixgr:truth:InvalidPUCCHHARQCodebookBinding", ...
                "Every HARQ-ACK bit in a physical PUCCH occasion must have one unique logical PUCCH grant identity.");
        end
        observed.LogicalPUCCHGrantIdSet = char(strjoin(grantIds, "|"));
        observed.LogicalFeedbackCount = double(height(feedbackRow));
        csiPart1 = int8([]);
        csiPart2 = int8([]);
        csiIdentity = strtrim(string(sixgr.util.structGet( ...
            csiReport, "ReportIdentity", "")));
        hasCSI = strlength(csiIdentity) > 0;
        if hasCSI
            csiPart1 = int8(sixgr.runtime.RawCSVArrayCodec.decode( ...
                sixgr.util.structGet(csiReport, "CSIPart1BitsToken", "")));
            csiPart2 = int8(sixgr.runtime.RawCSVArrayCodec.decode( ...
                sixgr.util.structGet(csiReport, "CSIPart2BitsToken", "")));
            observed.CSIReportIdentity = char(csiIdentity);
            observed.LogicalPUCCHGrantIdSet = char(strjoin( ...
                [grantIds; "CSI:" + csiIdentity], "|"));
            observed.LogicalFeedbackCount = double(height(feedbackRow) + 1);
        end
        pucchSNR_dB = sixgr.truth.resolvePUCCHConfiguredSNRMetadata( ...
            state, cfgU);
        trialIdx = max(1, round(double(sixgr.util.structGet(state, "CurrentSlot", 1))));
        sourceSlot = double(sixgr.truth.CoupledTruthRuntime.rowValue( ...
            row,"SourceSlot",trialIdx-1));
        dueSlot = double(sixgr.truth.CoupledTruthRuntime.rowValue( ...
            row,"ScheduledAbsoluteSlot", ...
            sixgr.truth.CoupledTruthRuntime.rowValue(row,"DueSlot",trialIdx)));
        k1 = dueSlot-sourceSlot;
        symbolsPerSlot = double(sixgr.util.structGet(state,"SymbolsPerSlot",14));
        ownership = repmat('F',1,symbolsPerSlot);
        [~,~,~,partition] = sixgr.truth.CoupledTruthRuntime.slotDuplexState( ...
            cfgU,dueSlot);
        ownership = localApplyOwnership(ownership, ...
            sixgr.util.structGet(partition,"DLSymbolAllocation",[0 0]),'D');
        ownership = localApplyOwnership(ownership, ...
            sixgr.util.structGet(partition,"GuardSymbolAllocation",[0 0]),'G');
        ownership = localApplyOwnership(ownership, ...
            sixgr.util.structGet(partition,"ULSymbolAllocation",[0 symbolsPerSlot]),'U');
        [componentCarrier, activeULBWP] = ...
            sixgr.truth.CoupledTruthRuntime.resolvePUCCHCarrierBWP(cfgU, row);
        ueState = struct("UEID",ueIdx, ...
            "RNTI",double(sixgr.truth.CoupledTruthRuntime.rowValue( ...
            row,"RNTI",NaN)), ...
            "ServingCell",double(sixgr.truth.CoupledTruthRuntime.rowValue( ...
            row,"ServingCell",0)), ...
            "PUCCHCell",double(sixgr.truth.CoupledTruthRuntime.rowValue( ...
            row,"ServingCell",0)), ...
            "ComponentCarrier",componentCarrier,"ActiveULBWP",activeULBWP);
        physicalOccasionId = sprintf( ...
            "pucchoccasion:due=%d:ue=%d:rnti=%d:cell=%d:cc=%d:ulbwp=%d", ...
            round(dueSlot), round(ueIdx), round(double(ueState.RNTI)), ...
            round(double(ueState.ServingCell)), round(componentCarrier), ...
            round(activeULBWP));
        observed.PhysicalOccasionId = physicalOccasionId;
        explicitPRI = double(sixgr.truth.CoupledTruthRuntime.rowValue( ...
            row,"PRIValue",NaN));
        priPurpose = "harq";
        if hasCSI
            priPurpose = "csi";
        end
        priAuthority = sixgr.phy.pucch.resolveConfiguredPRI( ...
            cfgU,ueIdx,double(ueState.RNTI),explicitPRI,priPurpose);
        priProvenance = string(sixgr.truth.CoupledTruthRuntime.rowValue( ...
            row,"PRIProvenance",""));
        if ismissing(priProvenance) || strlength(strtrim(priProvenance)) == 0
            priProvenance = string(priAuthority.Source);
        end
        frameState = struct("K1",k1,"K1Source","decoded_dci", ...
            "PDSCHEndSlot",sourceSlot,"TargetSlot",dueSlot, ...
            "DecodedPRI",priAuthority.PRIValue,"PRIFieldWidth",3, ...
            "PRIProvenance",char(priProvenance), ...
            "FirstCCE",0,"NumCCE",24, ...
            "SlotSymbolOwnership",string(ownership), ...
            "FlexibleResolutionProvided",false, ...
            "TriggeringEventID",sixgr.truth.CoupledTruthRuntime.rowValue( ...
            row,"PUCCHGrantId",physicalOccasionId));
        if hasCSI
            connected=sixgr.phy.pucch.PUCCHConfigBuilder.connectedCombined( ...
                cfgU,ueState,expectedBits,csiPart1,csiPart2,frameState);
        else
            connected=sixgr.phy.pucch.PUCCHConfigBuilder.connectedHARQ( ...
                cfgU,ueState,expectedBits,frameState);
        end
        if height(feedbackRow) == 1 && ~hasCSI
            sixgr.truth.CoupledTruthRuntime.assertPUCCHAssignmentMatchesGrant( ...
                connected.Assignment,row,"desired");
        end
        carrier=sixgr.phy.grid.makeCarrier(cfgU);
        channelProfile = sixgr.channel.resolveConcreteProfile(cfgU);
        [state,pucchInterferenceBundle] = ...
            sixgr.truth.CoupledTruthRuntime.buildPUCCHInterferenceBundle( ...
            state,feedbackRow);
        [state,pucchChannelState] = ...
            sixgr.truth.CoupledTruthRuntime.acquireRuntimeChannelStateForControl( ...
            state,cfgU,ueIdx,"UL");
        trial = sixgr.link.runPUCCHWaveformTrial(cfgU, ...
            "Carrier",carrier,"Assignment",connected.Assignment, ...
            "Report",connected.Report, ...
            "ReceiverContext",connected.ReceiverContext, ...
            "SNR_dB",double(pucchSNR_dB), ...
            "ChannelProfile",channelProfile,"Seed",trialIdx, ...
            "InitialRuntimeChannelState",pucchChannelState, ...
            "InterferenceBundle",pucchInterferenceBundle);
        state = sixgr.truth.CoupledTruthRuntime.commitRuntimeChannelState( ...
            state,sixgr.util.structGet(trial, ...
            "UpdatedRuntimeChannelState",struct()));
        executedPUCCHTx = sixgr.util.structGet(trial, "Transmitter", struct());
        if isstruct(executedPUCCHTx) && isfield(executedPUCCHTx, "PUCCHIndices")
            pucchRET = sixgr.truth.buildObservedREAllocation(executedPUCCHTx, ...
                "Direction", "UL", "Channel", "PUCCH", ...
                "AbsoluteSlot", max(0, round(dueSlot) - 1), ...
                "CellID", double(sixgr.truth.CoupledTruthRuntime.rowValue( ...
                    row,"ServingCell",NaN)), "UEID", ueIdx, ...
                "AllocationID", "pucch_slot_" + string(max(0, round(dueSlot) - 1)) + ...
                    "_ue_" + string(ueIdx));
            state.ObservedREAllocationTable = ...
                sixgr.truth.CoupledTruthRuntime.appendObservedREAllocation( ...
                sixgr.util.structGet(state, "ObservedREAllocationTable", table()), ...
                pucchRET);
        end
        decodedWireBits = int8(sixgr.util.structGet(trial, "DecodedBits", int8([])));
        serializedReport = sixgr.phy.pucch.UCIReportSerializer.serialize( ...
            connected.Report);
        decodedReport = struct("InformationBits", int8([]), ...
            "HARQACKBits", int8([]), "CSIPart1Bits", int8([]), ...
            "CSIPart2Bits", int8([]), "PaddingBits", int8([]));
        wireLayoutOk = false;
        try
            decodedReport = sixgr.phy.pucch.UCIReportSerializer. ...
                extractDecodedInformationBits(serializedReport, decodedWireBits);
            wireLayoutOk = true;
        catch ME
            if ~strcmp(ME.identifier, "sixgr:phy:pucch:UCILengthMismatch")
                rethrow(ME);
            end
        end
        decodedBits = int8(decodedReport.HARQACKBits);
        crcApplicable = logical(sixgr.util.structGet(trial, "CRCApplicable", false));
        crcPass = true;
        if crcApplicable
            crcPassRaw = double(sixgr.util.structGet(trial, "CRCPass", NaN));
            crcPass = isfinite(crcPassRaw) && logical(crcPassRaw);
        end
        receiverUsable = logical(sixgr.util.structGet(trial, "ReceiverUsable", false));
        dtxFlag = logical(sixgr.util.structGet(trial, "DTXFlag", ...
            sixgr.util.structGet(trial, "ReceiverDTX", false)));
        contentMatch = logical(sixgr.util.structGet(trial, ...
            "UCIContentMatch", false));
        layoutLengthsOk = wireLayoutOk && ...
            numel(decodedBits) == numel(expectedBits) && ...
            (~hasCSI || (numel(decodedReport.CSIPart1Bits) == numel(csiPart1) && ...
                numel(decodedReport.CSIPart2Bits) == numel(csiPart2)));
        observed.DecodeOk = receiverUsable && ~dtxFlag && contentMatch && ...
            layoutLengthsOk && (~crcApplicable || crcPass);
        observed.DTXFlag = logical(sixgr.util.structGet(trial, "DTXFlag", ...
            sixgr.util.structGet(trial,"ReceiverDTX",false)));
        observed.MissedFeedback = ~logical(observed.DecodeOk);
        observed.DecodedBits = decodedBits;
        observed.CSIWireLayoutOk = logical(wireLayoutOk);
        observed.DecodedCSIPart1Bits = int8(decodedReport.CSIPart1Bits);
        observed.DecodedCSIPart2Bits = int8(decodedReport.CSIPart2Bits);
        observed.DecodedCSIInformationBits = int8([ ...
            decodedReport.CSIPart1Bits; decodedReport.CSIPart2Bits]);
        observed.CSIDecodeOk = logical(hasCSI && observed.DecodeOk);
        if crcApplicable
            observed.CSICRCPass = double(crcPass);
        end
        observed.DecodedAck = ~isempty(decodedBits) && logical(decodedBits(1));
        observed.ObservedAck = logical(observed.DecodeOk && observed.DecodedAck);
        observed.FalseAck = logical(~expectedAck && observed.ObservedAck);
        observed.FalseNack = logical(expectedAck && observed.DecodeOk && ~observed.ObservedAck);
        trialCrashed = logical(sixgr.util.structGet(trial, "Crash", false));
        if observed.DecodeOk
            if ueIdx > numel(state.LastSuccessfulPUCCHSlotByUE)
                state.LastSuccessfulPUCCHSlotByUE(ueIdx, 1) = NaN;
            end
            state.LastSuccessfulPUCCHSlotByUE(ueIdx) = double(sixgr.util.structGet(state, "CurrentSlot", NaN));
        else
            if ueIdx > numel(state.PUCCHFailureCount)
                state.PUCCHFailureCount(ueIdx, 1) = 0;
            end
            state.PUCCHFailureCount(ueIdx) = double(state.PUCCHFailureCount(ueIdx)) + 1;
            if trialCrashed
                if ueIdx > numel(state.PUCCHCrashCount)
                    state.PUCCHCrashCount(ueIdx, 1) = 0;
                end
                state.PUCCHCrashCount(ueIdx) = double(state.PUCCHCrashCount(ueIdx)) + 1;
            end
        end
        trialFeedbackRow = feedbackRow;
        if hasCSI
            % Pending-feedback rows originate from scalar structs, so older
            % concatenations can leave UCIType as a cell-of-char table
            % variable.  Assign through the canonical text-column helper;
            % direct string assignment into that legacy representation
            % crashes exactly when HARQ-ACK and CSI share a PUCCH occasion.
            trialFeedbackRow = sixgr.truth.CoupledTruthRuntime.setStringColumn( ...
                trialFeedbackRow, "UCIType", "harq_ack+csi_part1_part2", true);
            trialFeedbackRow.UCIBitCount(:) = double(numel(expectedBits) + ...
                numel(csiPart1) + numel(csiPart2));
        end
        state = sixgr.truth.CoupledTruthRuntime.appendPUCCHFeedbackTrial( ...
            state, trialFeedbackRow, trial, observed);
    end

    function rows = validateAndOrderPUCCHPhysicalOccasion(rows)
        groups = sixgr.truth.CoupledTruthRuntime.groupPUCCHRowsByPhysicalOccasion(rows);
        if numel(groups) ~= 1
            error("sixgr:truth:MixedPUCCHPhysicalOccasions", ...
                "One waveform execution may contain HARQ-ACK bits from exactly one UE physical PUCCH occasion.");
        end
        rows = groups{1};
    end

    function state = appendPUCCHFeedbackTrial(state, feedbackRow, trial, observed)
        if ~(istable(feedbackRow) && height(feedbackRow) >= 1)
            return;
        end
        fbRow = feedbackRow(1, :);
        if nargin < 4 || ~isstruct(observed)
            observed = struct("ExpectedAck", false, "ObservedAck", false, "DecodedAck", false, ...
                "DecodeOk", false, "DTXFlag", false, "MissedFeedback", true, ...
                "FalseAck", false, "FalseNack", false);
        end
        if nargin < 3 || ~isstruct(trial)
            trial = struct();
        end
        expectedBits = sixgr.truth.CoupledTruthRuntime.normalizeUCIBits( ...
            sixgr.util.structGet(trial, "ExpectedBits", int8(1)));
        decodedBits = sixgr.truth.CoupledTruthRuntime.normalizeUCIBits( ...
            sixgr.util.structGet(trial, "DecodedBits", int8([])));
        resolvedFormatForEvidence = double(sixgr.util.structGet(trial, "ResolvedFormat", NaN));
        expectedBitCount = double(sixgr.util.structGet(trial, "ExpectedBitCount", numel(expectedBits)));
        decodedBitCount = double(sixgr.util.structGet(trial, "DecodedBitCount", numel(decodedBits)));
        uciCrcBitCount = double(sixgr.util.structGet(trial, "UCICRCBitCount", ...
            sixgr.truth.CoupledTruthRuntime.pucchUCICRCBitCount(expectedBitCount, resolvedFormatForEvidence)));
        uciCodedBitCount = double(sixgr.util.structGet(trial, "UCICodedBitCount", ...
            sixgr.truth.CoupledTruthRuntime.pucchUCICodedBitCount(trial, resolvedFormatForEvidence)));
        dmrsReCountForEvidence = double(sixgr.util.structGet(trial, "PUCCHDMRSRECount", NaN));
        ack = logical(sixgr.util.structGet(observed, "ObservedAck", false));
        decodeOk = logical(sixgr.util.structGet(observed, "DecodeOk", false));
        detectionUsable = logical(sixgr.util.structGet(trial, "DetectionUsable", true));
        crcApplicable = logical(sixgr.util.structGet(trial, "CRCApplicable", uciCrcBitCount > 0));
        if crcApplicable && detectionUsable
            crcPassValue = double(decodeOk);
        else
            crcPassValue = NaN;
        end
        uciContentMatch = logical(sixgr.util.structGet(trial, "UCIContentMatch", ...
            (double(sixgr.util.structGet(trial, "BitErrors", 1)) == 0 && ...
            double(sixgr.util.structGet(trial, "BitsCompared", 0)) == numel(sixgr.util.structGet(trial, "ExpectedBits", int8(1))))));
        crcOutcome = string(sixgr.util.structGet(trial, "CRCOutcome", ...
            sixgr.truth.CoupledTruthRuntime.ternaryString(crcApplicable, ...
            sixgr.truth.CoupledTruthRuntime.ternaryString(decodeOk, "pass", "fail"), "not_applicable")));
        detectionOutcome = string(sixgr.util.structGet(trial, "DetectionOutcome", ...
            sixgr.truth.CoupledTruthRuntime.ternaryString(detectionUsable, ...
            sixgr.truth.CoupledTruthRuntime.ternaryString(uciContentMatch, "detected", "missed"), "unavailable")));
        status = string(sixgr.util.structGet(trial, "Status", ...
            sixgr.truth.CoupledTruthRuntime.ternaryString(ack, "PASS", "FAIL")));
        uciType = lower(strtrim(string(sixgr.truth.CoupledTruthRuntime. ...
            rowValue(fbRow, "UCIType", "harq_ack"))));
        isCSIReport = contains(uciType, "csi");
        runtimeConsumer = "HARQEntity.onFeedback";
        stateChangeDefinition = ...
            "harq_feedback_consumed_by_runtime_harq_and_scheduler";
        if isCSIReport
            runtimeConsumer = "CoupledTruthRuntime.processDueFeedback.CSI";
            stateChangeDefinition = ...
                "receiver_decoded_csi_consumed_by_link_adaptation_scheduler";
        end
        expectedAck = sixgr.truth.CoupledTruthRuntime.rowExpectedPUCCHAck(fbRow);
        logicalGrantIds = string(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
            feedbackRow, "PUCCHGrantId", repmat("", height(feedbackRow), 1)));
        logicalGrantIdSet = string(sixgr.util.structGet(observed, ...
            "LogicalPUCCHGrantIdSet", strjoin(logicalGrantIds, "|")));
        logicalFeedbackCount = double(sixgr.util.structGet(observed, ...
            "LogicalFeedbackCount", height(feedbackRow)));
        sourceSlots = double(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
            feedbackRow, "SourceSlot", nan(height(feedbackRow), 1)));
        harqProcesses = double(sixgr.truth.CoupledTruthRuntime.tableColumnOrDefault( ...
            feedbackRow, "HarqID", nan(height(feedbackRow), 1)));
        physicalOccasionId = string(sixgr.util.structGet( ...
            observed, "PhysicalOccasionId", ""));
        exportedGrantId = string(logicalGrantIds(1));
        if height(feedbackRow) > 1
            exportedGrantId = physicalOccasionId;
        end
        row = struct( ...
            "Direction", "UL", ...
            "Frame", double(sixgr.util.structGet(state, "CurrentFrame", NaN)), ...
            "Slot", double(sixgr.util.structGet(state, "CurrentSlot", NaN)), ...
            "UEIndex", double(sixgr.truth.CoupledTruthRuntime.rowValue(fbRow, "UEIndex", NaN)), ...
            "UEID", double(sixgr.truth.CoupledTruthRuntime.rowValue(fbRow, "UEIndex", NaN)), ...
